INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (1147, 'https://stutenseekinderkalender.de', 'Eltern-Kind-Treff „Frühe Hilfen“', '2026-05-07', '2026-05-07', '10:15', 'Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297', 'Frühe Hilfen Landkreis Karlsruhe', 'Einmal im Monat treffen sich Mütter und Väter mit ihren Kindern im Alter von 0 – 2 Jahren unter der Leitung einer Sozialpädagogin.
