INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (1217, 'https://stutenseekinderkalender.de', 'Ganzheitliche Schwangerschaftsgymnastik', '2026-05-21', '2026-05-21', '17:00', 'Sporthalle, Heinrich-Heine-Straße 1, Stutensee-Spöck, 76297', 'vhs Karlsruhe Land', 'Eine Schwangerschaft ist immer etwas Einzigartiges und Besonderes. Der Körper stellt sich um, bereitet sich auf die kommenden Wochen und Monaten vor und verändert sich.
Um die bevorstehenden Veränderungen für dich und dein Kind positiv zu unterstützen, zeige ich dir im Kurs angepasste Kraftübungen, die deinen Körper ganzheitlich kräftigen sowie fit halten. Zudem minimieren wir gemeinsam mit speziellen Entspannungseinheiten Beschwerden wie Rückenschmerzen, Beckenbodenschwäche oder auftretende Wachstumsschmerzen.
Im Kurs kläre ich dich zudem auf, welche Veränderungen dein Körper in den kommenden Schwangerschaftswochen durchlaufen wird und wie du deinen Alltag optimal anpassen kannst.
Ein Austausch über deine Wunschthemen und Fragen sind herzlich willkommen!
Du kannst den Kurs beim Wohlergehen bis zum Ende der Schwangerschaft besuchen.
Bitte mitbringen: Bequeme Kleidung, Turnschuhe, Getränk.
Kursgebühr: 33,00 €
Bei folgenden Punkten bitte erst deine(n) Frauenarzt/Frauenärztin konsultieren und die Kursteilnahme abklären lassen:
– Risikoschwangerschaft
– Bluthochdruck
– Schwangerschaftsdiabetes
Geschwisterkinder können mitgebracht werden. Es werden Spielmöglichkeiten bereitgestellt.
', 'https://stutenseekinderkalender.de/event/ganzheitliche-schwangerschaftsgymnastik-2/2026-05-21/', '2bfbda6cfcab049234f972cf3194d442e49a7c8573cedf28cfe57bf00706d280', '2026-04-25 16:35:37');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (1218, 'https://stutenseekinderkalender.de', 'Teen Girls im GrauBau', '2026-05-21', '2026-05-21', '18:00', 'GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297', 'GrauBau Jugendzentrum Stutensee', 'Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr
Veranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de

