INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (1221, 'https://stutenseekinderkalender.de', 'Fit in der Schwangerschaft', '2026-05-22', '2026-05-22', '09:00', 'Mamawerk, Kirchstraße 9, Stutensee-Spöck, 76297', 'Mamawerk', 'Übungen die auf die Schwangerschaft zugeschnitten sind, halten dich fit und bereiten auf die Geburt vor. Dein Beckenboden wird gestärkt, um auch nach der Geburt standfest zu bleiben. In einer kleinen Gruppe aktivieren und mobilisieren wir deinen Körper. Außerdem informiere ich dich rund um das Thema Schwangerschaft und Sport.
