INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (1325, 'https://stutenseekinderkalender.de', '2. Großes Stutenseer Kinderfest in Blankenloch', '2026-06-13', '2026-06-13', '13:00', 'TSG Blankenloch, Mühlenweg 4a, Stutensee-Blankenloch, 76297', 'Gesamtelternbeirat und Eltern der Stutenseer Kindergärten', 'Das zweite Stutenseer Kinderfest findet im Juni 2026 statt und richtet sich an Familien mit Kindern. Auf dem Gelände erwartet die Besucher:innen ein vielfältiges Angebot mit Hüpfburg, Spielstationen, Tombola, Kinderschminken sowie weiteren Mitmachaktionen. Für Speisen und Getränke ist gesorgt, unter anderem mit einem Eisfahrrad.
Das Kinderfest wird vom Gesamtelternbeirat und den Eltern der Stutenseer Kindergärten organisiert und ausgerichtet.
Die Veranstaltung steht unter der Schirmherrschaft von Oberbürgermeisterin Petra Becker.
