INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (1352, 'https://stutenseekinderkalender.de', 'Fit in der Schwangerschaft', '2026-06-19', '2026-06-19', '09:00', 'Mamawerk, Kirchstraße 9, Stutensee-Spöck, 76297', 'Mamawerk', 'Übungen die auf die Schwangerschaft zugeschnitten sind, halten dich fit und bereiten auf die Geburt vor. Dein Beckenboden wird gestärkt, um auch nach der Geburt standfest zu bleiben. In einer kleinen Gruppe aktivieren und mobilisieren wir deinen Körper. Außerdem informiere ich dich rund um das Thema Schwangerschaft und Sport.
Der Kurs hat 8 Termine Die maximale Teilnehmerzahl beträgt 10 Teilnehmerinnen.
Voraussetzungen: Dein Frauenarzt sollte dir vorab eine komplikationslose Schwangerschaft bestätigen und dir Bescheinigen, dass leichter Sport getätigt werden darf.
 ', 'https://stutenseekinderkalender.de/event/fit-in-der-schwangerschaft/2026-06-19/', 'c90d58463af751e0d232ed86fb435421014e00ad0b1b8f7ee407d62612562e4c', '2026-04-25 16:35:37');
