INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (1354, 'https://stutenseekinderkalender.de', 'Eltern-Baby-Treff', '2026-06-19', '2026-06-19', '09:30', 'Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297', 'Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus', '
In dieser offenen Krabbelgruppe können Eltern und Kinder gemeinsam spielen, singen und entdecken. Die Treffen bieten Raum für Bewegung, kreative Spiele und Austausch in entspannter Atmosphäre. Auch spontane Teilnahme ist möglich – ohne Anmeldung und kostenfrei.


