INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (1360, 'https://stutenseekinderkalender.de', 'Tag der offenen Tür – Waldorfkindergarten Stutensee', '2026-06-20', '2026-06-20', '14:00', 'Waldorfkindergarten Stutensee, Rheinstraße Ost 12, Stutensee, 76297', 'Waldorfkindergarten Stutensee', 'Der Waldorfkindergarten Stutensee lädt herzlich zum Tag der offenen Tür ein. Besucherinnen und Besucher haben die Gelegenheit, den Kindergarten kennenzulernen, Einblicke in den Alltag mit den Kindern zu gewinnen und die besondere Atmosphäre vor Ort zu erleben.', 'https://stutenseekinderkalender.de/event/tag-der-offenen-tuer-waldorfkindergarten-stutensee-2026/', '89ca26a349c362189787716a05332ee285b6337eab7859017413cb5cab505502', '2026-04-25 16:35:37');
