INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (1539, 'https://stutenseekinderkalender.de', 'Tanzen für die Kleinsten (4-6 Jahre)', '2026-08-01', '2026-08-01', '11:15', 'Tanzgruppe Rowan Berry, Stutensee-Spöck, 76297', 'Tanzgruppe Rowan Berry', 'Ein regelmäßiges Tanzangebot für Kinder im Alter von 4 bis 6 Jahren. In spielerischer Form werden Bewegung, Musik und Rhythmus miteinander verbunden. Die Kinder sammeln erste Tanzerfahrungen und beschäftigen sich mit Ausdruck und Koordination. Das Angebot wird von einer ausgebildeten Diplom-Tanzpädagogin geleitet.
Weitere Informationen und Anmeldung unter: 0176 38172576

 ', 'https://stutenseekinderkalender.de/event/ryabinushka-tanzen-fuer-die-kleinsten-4-6-jahre/2026-08-01/', 'd50bee5307e1ff09350ea17b3a7aca846eed75196c87688e0ddb09cdc31987dc', '2026-04-25 16:35:37');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (1540, 'https://stutenseekinderkalender.de', 'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal', '2026-08-03', '2026-08-03', '09:00', 'Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297', 'Ev. Kirchengemeinde Friedrichstal', '
In der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.
Montags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.

Weitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.
Ansprechpartnerin:
Sabrina Strohal, Tel. 387483 oder 0160 98567729
Flyer Kükenstube 2025', 'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2026-08-03/', '9a588539d4c2d7f618204a3124dda0531344ffef042a7f9c846c73534c36db9a', '2026-04-25 16:35:37');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (1541, 'https://stutenseekinderkalender.de', 'Eltern-Baby-Café', '2026-08-03', '2026-08-03', '10:00', 'Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297', 'Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.', 'Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.
Die Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.
Die Babys haben Spaß miteinander beim Singen, Spielen und Basteln.
