INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (1668, 'https://stutenseekinderkalender.de', 'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal', '2026-09-03', '2026-09-03', '09:00', 'Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297', 'Ev. Kirchengemeinde Friedrichstal', '
In der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.
