INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (1839, 'https://stutenseekinderkalender.de', 'Offene Sprechstunde der Psychologischen Beratungsstelle für Eltern, Kinder und Jugendliche des Landkreises Karlsruhe', '2026-10-14', '2026-10-14', '12:00', 'Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297', 'Psychologische Beratungsstelle für Eltern, Kinder und Jugendliche des Landkreises Karlsruhe', 'Für Eltern, Kinder und Jugendliche bietet die psychologischen Beratungsstelle des Landkreises Karlsruhe bei Fragen zu Erziehung, Entwicklung, familiären und persönlichen Problemen monatlich eine offene Sprechstunde im Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V. an – kostenfrei, vertraulich und ohne Anmeldung.
