INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (2068, 'https://stutenseekinderkalender.de', 'Offene Sprechstunde der Psychologischen Beratungsstelle für Eltern, Kinder und Jugendliche des Landkreises Karlsruhe', '2026-12-09', '2026-12-09', '12:00', 'Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297', 'Psychologische Beratungsstelle für Eltern, Kinder und Jugendliche des Landkreises Karlsruhe', 'Für Eltern, Kinder und Jugendliche bietet die psychologischen Beratungsstelle des Landkreises Karlsruhe bei Fragen zu Erziehung, Entwicklung, familiären und persönlichen Problemen monatlich eine offene Sprechstunde im Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V. an – kostenfrei, vertraulich und ohne Anmeldung.
Mittwoch 12 – 15 Uhr (einmal im Monat): 11. März, 15. April, 13. Mai, 10. Juni, 8. Juli, 16. September, 14. Oktober, 11. November, 9. Dezember 2026
