INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (2085, 'https://stutenseekinderkalender.de', 'Spiele-Treff vom Teenie bis zum Oldie', '2026-12-14', '2026-12-14', '16:00', 'Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297', 'Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.', 'Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.
