INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (2086, 'https://stutenseekinderkalender.de', 'Briefmarkentauschtage', '2026-12-14', '2026-12-14', '16:00', 'Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297', 'Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.', 'Alle Kinder, Jugendlichen, Erwachsenen und Senioren, die sich für Briefmarken interessieren, mit dem Sammeln anfangen oder tauschen möchten, können gerne unverbindlich reinschauen.

Montag 16 – 17 Uhr (einmal im Monat)
