INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (2087, 'https://stutenseekinderkalender.de', 'Kinder- und Jugendtraining – Wilde 13', '2026-12-14', '2026-12-14', '18:00', 'Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297', 'BSG Wilde 13 Stutensee e.V.', 'Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.
Das Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.
Kontakt bei Fragen: boehm.uwe@outlook.com
', 'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2026-12-14/', '0e46fc2f68cafc4ab5128747163a46b5caab6d2c48422810c6bd845c8b76ab1c', '2026-04-25 16:35:37');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (2088, 'https://stutenseekinderkalender.de', 'Krabbelkäfer Stutensee-Büchig – gemütliches Beisammensein mit Frühstück', '2026-12-15', '2026-12-15', '09:00', 'Heilig-Geist-Gemeinde Büchig, Akazienweg 7, Stutensee-Büchig, 76297', 'Heilig-Geist-Gemeinde Büchig', 'Herzliche Einladung an alle Kinder ab 0 Jahren mit Begleitung durch Eltern, Großeltern, Tante, Onkel oder andere Bezugspersonen.In entspannter Atmosphäre wird gemeinsam gefrühstückt, gespielt, gebastelt und sich ausgetauscht.
Auch Schwangere sind herzlich willkommen!Neue Gesichter sind jederzeit gerne gesehen – einfach vorbeikommen und mitmachen.
Zurzeit in der Belchenstraße (privat bei Melanie Reuter).
Kontakt zum Veranstalter

Ansprechpartnerin: Melanie Reuter
E-Mail: info@krabbelkäfer-stutensee.de
oder übers Pfarramt

 
Hinweis
Hier im Familienkalender werden die Infos teilweise automatisch zusammengetragen. Es ist nicht auszuschließen, dass die Angaben nicht vollständig oder aktuell sind – bitte prüft die Informationen noch einmal direkt beim Veranstalter.', 'https://stutenseekinderkalender.de/event/krabbelkaefer-stutensee-buechig-gemuetliches-beisammensein-mit-fruehstueck/2026-12-15/', '73875f41113d259999e895f5810c23bbc6034ba6fab985ce46352a932264fdd5', '2026-04-25 16:35:37');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (2089, 'https://stutenseekinderkalender.de', 'Krabbelgruppe in Spöck', '2026-12-15', '2026-12-15', '09:30', 'Ev. Gemeindehaus Spöck, Fröbelweg 1, Stutensee-Spöck, 76297', 'CVJM Spöck e.V.', 'Ein gemütliches Treffen für Eltern, Großeltern und ihre Kinder von 0 bis etwa 3 Jahren.Bei Liedern, Fingerspielen und kleinen Aktionen entdecken die Kleinsten spielerisch ihre Umgebung, während die Erwachsenen Zeit für Austausch und Gespräche haben. Auch gemeinsames Frühstück oder Bastelaktionen stehen immer wieder auf dem Programm.
In den Schulferien findet die Krabbelgruppe nicht statt.
Anmeldung erforderlich: Lena Schmidt, family@cvjm-spoeck.de
', 'https://stutenseekinderkalender.de/event/krabbelgruppe-in-spoeck/2026-12-15/', 'b9768ca1d3bb9bb252e10569db026e8e878deb2c03ed336f6a8ce481367da36a', '2026-04-25 16:35:37');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (2090, 'https://stutenseekinderkalender.de', 'Seepferdchengarde (6–10 Jahre)', '2026-12-15', '2026-12-15', '16:00', 'Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297', 'Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.', 'Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.

Dienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr
Veranstalter: Karnevalsclub Die Piraten Blankenloch e. V.
', 'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre-2/2026-12-15/', '00f052e5e56b8ae7e5ef23568bde7211911d974a6ee88ec870c9d3d945f02443', '2026-04-25 16:35:37');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (2091, 'https://stutenseekinderkalender.de', 'Schach für Schüler, Jugendliche & Anfänger', '2026-12-15', '2026-12-15', '16:30', 'Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298', 'Schachclub Blankenloch 1947 e.V.', 'Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.
Ein Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.
Anmeldung: Gerhard Crocoll, 015233943935', 'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2026-12-15/', '820041cc6a69d5ca7f7d0091cf9e3065a62d4d3f0930fe470e00f6de62d16c24', '2026-04-25 16:35:37');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (2092, 'https://stutenseekinderkalender.de', 'Pfadfinder*innengruppe Wölflinge', '2026-12-15', '2026-12-15', '17:30', 'Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297', 'Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler', 'Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.
Der Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!
Unsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.', 'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2026-12-15/', '61dc24f89fef13a9b25cc27d491e2cbe29d2253556a048622d7bcbbcad7d7da8', '2026-04-25 16:35:37');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (2093, 'https://stutenseekinderkalender.de', 'Pfadfinder*innengruppe (11–15 Jahre)', '2026-12-15', '2026-12-15', '17:30', 'Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297', 'Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler', 'Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.
Geländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.
Höhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).


Der Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!
Unsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.




', 'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2026-12-15/', '1e06cf38da3d905f227e9b557b24a2e26bce9c4e28eff2e9210afea36ef8a965', '2026-04-25 16:35:37');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (2094, 'https://stutenseekinderkalender.de', 'Korallengarde (10–14 Jahre)', '2026-12-15', '2026-12-15', '18:00', 'Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297', 'Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.', 'Die Korallengarde verbindet Präzision, Ausstrahlung und Teamgeist. Kinder und Jugendliche zwischen 10 und 14 Jahren trainieren anspruchsvolle Choreografien und bereiten sich auf Auftritte in der Faschingszeit vor.

