INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (2126, 'https://stutenseekinderkalender.de', 'Spielzeit im GrauBau', '2026-12-23', '2026-12-23', '15:00', 'GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297', 'GrauBau Jugendzentrum Stutensee', 'In der Spielzeit im GrauBau erwartet euch jede Woche ein neues Abenteuer: spannende Experimente, kreative Bastelaktionen, Bewegungsspiele, Filme und gemeinsames Kochen oder Backen. Für Kinder zwischen 6 und 10 Jahren.
