INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (2181, 'https://stutenseekinderkalender.de', 'Abenteuer-Zwerge (4-6 Jahre)', '2027-01-06', '2027-01-06', '16:15', 'Gymnasiumstraße 16, Stutensee-Blankenloch, Gymnasiumstraße 16, Stutensee-Blankenloch, 76297', 'Melanie Nagel', 'Eine bunte Gruppenstunde für kleine Entdecker. Einmal pro Woche wird gemeinsam gespielt, gebastelt, gesungen, sich bewegt und die Welt entdeckt.

Start: 15.04.2026
