INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (2418, 'https://stutenseekinderkalender.de', 'Tee- und Spielstube', '2027-03-11', '2027-03-11', '16:00', 'Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298', 'Flüchtlingshilfe Stutensee e.V.', 'Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.

Für Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen
Jeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)

Anmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de ', 'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-03-11/', 'c29a73fdd303ad1fa64a744b8e21dbdf7834047cbf2834f674c4bf8265e0620b', '2026-04-25 16:35:37');
