INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (2492, 'https://stutenseekinderkalender.de', 'Eltern-Kind-Kreis in Friedrichstal', '2027-03-31', '2027-03-31', '10:00', 'Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297', 'Ev. Kirchengemeinde Friedrichstal', 'Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.
Ansprechpartnerin: Corinna Konrad, 01725618123', 'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2027-03-31/', 'b2e18195bb321f3a0441da0ed8d9509f982fe781450ac043c1a09f576b0870da', '2026-04-25 16:35:37');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (2493, 'https://stutenseekinderkalender.de', 'Abenteuer-Zwerge (4-6 Jahre)', '2027-03-31', '2027-03-31', '16:15', 'Gymnasiumstraße 16, Stutensee-Blankenloch, Gymnasiumstraße 16, Stutensee-Blankenloch, 76297', 'Melanie Nagel', 'Eine bunte Gruppenstunde für kleine Entdecker. Einmal pro Woche wird gemeinsam gespielt, gebastelt, gesungen, sich bewegt und die Welt entdeckt.

Start: 15.04.2026
Termin: mittwochs
