INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (2527, 'https://stutenseekinderkalender.de', 'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee', '2027-04-09', '2027-04-09', '13:15', 'Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297', 'Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium', 'In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.
Interessierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.
Weitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de', 'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2027-04-09/', '8ff183d8c0147048d2f9bdc005d4a319cbd6277d5b6a3212d5db4e6a31058a92', '2026-04-25 16:35:37');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (2528, 'https://stutenseekinderkalender.de', 'Kreativfreitag im GrauBau', '2027-04-09', '2027-04-09', '14:00', 'GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297', 'GrauBau Jugendzentrum Stutensee', 'Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. 
Veranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de

Hinweis
