INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (3095, 'https://stutenseekinderkalender.de', 'Eltern-Kind-Kreis in Friedrichstal', '2027-09-15', '2027-09-15', '10:00', 'Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297', 'Ev. Kirchengemeinde Friedrichstal', 'Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.
