INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (3240, 'https://stutenseekinderkalender.de', 'Pfadfinder*innengruppe Wölflinge', '2027-10-26', '2027-10-26', '17:30', 'Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297', 'Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler', 'Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.
Der Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!
Unsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.', 'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2027-10-26/', '3cc93f860bb52c1ce20192a85a0bc59d86dfc772fc7597f6395265aafa3d3771', '2026-04-25 16:35:37');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (3241, 'https://stutenseekinderkalender.de', 'Pfadfinder*innengruppe (11–15 Jahre)', '2027-10-26', '2027-10-26', '17:30', 'Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297', 'Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler', 'Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.
Geländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.
Höhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).


Der Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!
Unsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.




', 'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2027-10-26/', 'aaef63222a65090d80a7909081758248222db337f6a86161e3d2fc2d1effe80e', '2026-04-25 16:35:37');
