INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (3298, 'https://stutenseekinderkalender.de', 'Tee- und Spielstube', '2027-11-11', '2027-11-11', '16:00', 'Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298', 'Flüchtlingshilfe Stutensee e.V.', 'Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.

Für Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen
Jeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)

Anmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de ', 'https://stutenseekinderkalender.de/event/tee-und-spielstube/2027-11-11/', '618d740bbb41b7e71b89d6acee2a7129a4aa421e7d5c0a3e850fcb5950ac41f9', '2026-04-25 16:35:37');
