INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (3372, 'https://stutenseekinderkalender.de', 'Krabbelgruppe Stutensee-Blankenloch', '2027-12-02', '2027-12-02', '09:30', 'Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297', 'Michaelisgemeinde Blankenloch', 'Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.
