INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (3553, 'https://stutenseekinderkalender.de', 'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee', '2028-01-21', '2028-01-21', '13:15', 'Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297', 'Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium', 'In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.
Interessierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.
Weitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de', 'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2028-01-21/', '4a866641f665ea8cb305effdafb3c1338232c57f5dd3139c8fc4256be9b9f5e6', '2026-04-25 16:35:37');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (3554, 'https://stutenseekinderkalender.de', 'Kreativfreitag im GrauBau', '2028-01-21', '2028-01-21', '14:00', 'GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297', 'GrauBau Jugendzentrum Stutensee', 'Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. 
Veranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de

