INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (3577, 'https://stutenseekinderkalender.de', 'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)', '2028-01-27', '2028-01-27', '18:30', 'DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297', 'DRK Blankenloch e.V.', 'Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.
