INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (4308, 'https://stutenseekinderkalender.de', 'Eltern-Baby-Café', '2028-08-21', '2028-08-21', '10:00', 'Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297', 'Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.', 'Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.
