INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (4384, 'https://stutenseekinderkalender.de', 'Spiele-Treff vom Teenie bis zum Oldie', '2028-09-11', '2028-09-11', '16:00', 'Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297', 'Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.', 'Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.
Begeisterte Spieler/innen freuen sich auf Mitspielende jeden Alters. Es wird gespielt, was euch gefällt – schaut einfach rein!
Nicht in den Ferien.', 'https://stutenseekinderkalender.de/event/spiele-treff-vom-teenie-bis-zum-oldie/2028-09-11/', 'f26609dcf5272df86586217dce68967b2552d9e9e183f6510bef602789a8f3ac', '2026-04-25 16:35:37');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (4385, 'https://stutenseekinderkalender.de', 'Kinder- und Jugendtraining – Wilde 13', '2028-09-11', '2028-09-11', '18:00', 'Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297', 'BSG Wilde 13 Stutensee e.V.', 'Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.
Das Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.
Kontakt bei Fragen: boehm.uwe@outlook.com
', 'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-09-11/', '3d490d98d695a39dee68340bf3d86bed2a2c36dbe12fe554a4302afd009f50a3', '2026-04-25 16:35:37');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (4386, 'https://stutenseekinderkalender.de', 'Krabbelkäfer Stutensee-Büchig – gemütliches Beisammensein mit Frühstück', '2028-09-12', '2028-09-12', '09:00', 'Heilig-Geist-Gemeinde Büchig, Akazienweg 7, Stutensee-Büchig, 76297', 'Heilig-Geist-Gemeinde Büchig', 'Herzliche Einladung an alle Kinder ab 0 Jahren mit Begleitung durch Eltern, Großeltern, Tante, Onkel oder andere Bezugspersonen.In entspannter Atmosphäre wird gemeinsam gefrühstückt, gespielt, gebastelt und sich ausgetauscht.
Auch Schwangere sind herzlich willkommen!Neue Gesichter sind jederzeit gerne gesehen – einfach vorbeikommen und mitmachen.
Zurzeit in der Belchenstraße (privat bei Melanie Reuter).
Kontakt zum Veranstalter

Ansprechpartnerin: Melanie Reuter
E-Mail: info@krabbelkäfer-stutensee.de
oder übers Pfarramt

 
