INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (4436, 'https://stutenseekinderkalender.de', 'Krabbelkäfer Stutensee-Büchig – gemütliches Beisammensein mit Frühstück', '2028-09-26', '2028-09-26', '09:00', 'Heilig-Geist-Gemeinde Büchig, Akazienweg 7, Stutensee-Büchig, 76297', 'Heilig-Geist-Gemeinde Büchig', 'Herzliche Einladung an alle Kinder ab 0 Jahren mit Begleitung durch Eltern, Großeltern, Tante, Onkel oder andere Bezugspersonen.In entspannter Atmosphäre wird gemeinsam gefrühstückt, gespielt, gebastelt und sich ausgetauscht.
Auch Schwangere sind herzlich willkommen!Neue Gesichter sind jederzeit gerne gesehen – einfach vorbeikommen und mitmachen.
Zurzeit in der Belchenstraße (privat bei Melanie Reuter).
