INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (9528, 'https://stutenseekinderkalender.de', 'Kinder- und Jugendtraining – Wilde 13', '2029-01-01', '2029-01-01', '18:00', 'Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297', 'BSG Wilde 13 Stutensee e.V.', 'Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.
Das Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.
Kontakt bei Fragen: boehm.uwe@outlook.com
', 'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2029-01-01/', '2368d5134a353b9cfc69f74fc5bd78e61876596cbbef22231929b1a09d7a25dc', '2026-04-25 16:54:43');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (9529, 'https://stutenseekinderkalender.de', 'Krabbelkäfer Stutensee-Büchig – gemütliches Beisammensein mit Frühstück', '2029-01-02', '2029-01-02', '09:00', 'Heilig-Geist-Gemeinde Büchig, Akazienweg 7, Stutensee-Büchig, 76297', 'Heilig-Geist-Gemeinde Büchig', 'Herzliche Einladung an alle Kinder ab 0 Jahren mit Begleitung durch Eltern, Großeltern, Tante, Onkel oder andere Bezugspersonen.In entspannter Atmosphäre wird gemeinsam gefrühstückt, gespielt, gebastelt und sich ausgetauscht.
Auch Schwangere sind herzlich willkommen!Neue Gesichter sind jederzeit gerne gesehen – einfach vorbeikommen und mitmachen.
Zurzeit in der Belchenstraße (privat bei Melanie Reuter).
Kontakt zum Veranstalter

Ansprechpartnerin: Melanie Reuter
E-Mail: info@krabbelkäfer-stutensee.de
oder übers Pfarramt

 
