INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (9711, 'https://stutenseekinderkalender.de', 'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern', '2029-02-20', '2029-02-20', '19:00', 'Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297', 'Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus', 'Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.
Die Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.
Hinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.

Jeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)
Kostenfrei

Anmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)', 'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2029-02-20/', '1ee64d137e8613be7e6f081a41feefa575a0eed89d28e9e1e5cfbd1edce08182', '2026-04-25 16:54:43');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (9712, 'https://stutenseekinderkalender.de', 'Krabbelgruppe im ev. Gemeindehaus Staffort', '2029-02-21', '2029-02-21', '09:30', 'Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297', 'Kirchengemeinde Staffort-Büchenau', 'Bist du im Alter von 0 bis 3 Jahren?
Dann komm doch zum…

… Spielen
