INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (9946, 'https://stutenseekinderkalender.de', 'Modellbahn-AG am Thomas-Mann-Gymnasium Stutensee', '2029-04-27', '2029-04-27', '13:15', 'Thomas-Mann-Gymnasium Stutensee, Gymnasiumstr. 20, Stutensee-Blankenloch, 76297', 'Schul-Arbeitsgemeinschaft „Modellbahn“ Thomas-Mann-Gymnasium', 'In der Modellbahn-AG des TMG bauen Schülerinnen und Schüler eigene Modellbahnanlagen, gestalten Landschaften und beschäftigen sich mit Technik, Elektronik und Steuerung. Die AG besteht seit 1996 und wird von Mitgliedern aus verschiedenen Klassenstufen betrieben.
Interessierte Kinder und Jugendliche aus dem TMG, der EKRS und anderen Schulen der Region können teilnehmen.
Weitere Informationen auf der Website der Modellbahn-AG: www.modellbahn-ag.de', 'https://stutenseekinderkalender.de/event/modellbahn-ag-am-thomas-mann-gymnasium-stutensee/2029-04-27/', '048989109f455787c9d033e03d468c897159a5e7d030b252547ef7ef262eb5cf', '2026-04-25 16:54:43');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (9947, 'https://stutenseekinderkalender.de', 'Kreativfreitag im GrauBau', '2029-04-27', '2029-04-27', '14:00', 'GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297', 'GrauBau Jugendzentrum Stutensee', 'Am Kreativfreitag kannst du deiner Fantasie freien Lauf lassen! Ob Malen, Basteln, Gestalten oder einfach Ausprobieren – hier kannst du dich kreativ austoben, neue Ideen entdecken und den GrauBau ganz neu erleben. Du kannst kommen und gehen, wann du möchtest. Für Kinder und Jugendliche ab 10 Jahren. Jeden Freitag, 14:00 – 20:00 Uhr. 
Veranstalter & KontaktTelefon: 07244969-276E-Mail: patricia.pichlardt@stutensee.de

