INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (10351, 'https://stutenseekinderkalender.de', 'Eltern-Baby-Café', '2029-08-20', '2029-08-20', '10:00', 'Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297', 'Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.', 'Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.
Die Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.
