INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (10463, 'https://stutenseekinderkalender.de', 'Eltern-Kind-Kreis in Friedrichstal', '2029-09-19', '2029-09-19', '10:00', 'Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297', 'Ev. Kirchengemeinde Friedrichstal', 'Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.
Ansprechpartnerin: Corinna Konrad, 01725618123', 'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2029-09-19/', '932e2e23789941b17e0807b8998f76787422618187af874310e71d9256afb9df', '2026-04-25 16:54:43');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (10464, 'https://stutenseekinderkalender.de', 'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal', '2029-09-20', '2029-09-20', '09:00', 'Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297', 'Ev. Kirchengemeinde Friedrichstal', '
In der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.
Montags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.

