INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (35689, 'https://www.vhs-karlsruhe-land.de/standorte/stutensee/', 'Englisch B1.1 (Teil 5)', '2026-05-05', NULL, '19:00 - 20:30', 'Blankenloch, Altes Rathaus Hauptstraße 80 76297 Stutensee-Blankenloch', 'VHS Stutensee', 'In diesem Kurs bauen die Teilnehmenden ihre Grundkenntnisse der englischen Sprache und Kultur aus. Sie lernen es insbesondere, sich in den verschiedensten alltäglichen Situationen zu verständigen ebenso wie über gegenwärtige und vergangene Erlebnisse und über Vorhaben in der nahen Zukunft zu berichten. Dabei erweitern sie ihren Wortschatz und ihre mündlichen Ausdrucksfähigkeiten. Neben der Vermittlung der Sprache werden auch landeskundliche Aspekte behandelt. So bekommen die Teilnehmenden weitere interessante Einblicke in die Geschichte, die Kultur, die Traditionen und die Mentalität der englischsprachigen Länder.', 'https://www.vhs-karlsruhe-land.de/programm/sprachen/kw/bereich/kursdetails/kurs/L406H013SH/kursname/Englisch B11 Teil 5/kategorie-id/3', 'c84a835e524f64cf048d29550c3babdb0b0f52ec82be4e9997836c9ec645e970', '2026-04-26 14:42:06');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (35690, 'https://www.vhs-karlsruhe-land.de/standorte/stutensee/', 'Spanisch A1.2 - Wiederholung (Teil 3)', '2026-06-09', NULL, '18:00 - 19:30', 'Blankenloch, Altes Rathaus, Raum 1.3 Hauptstraße 80 76297 Stutensee-Blankenloch', 'VHS Stutensee', 'In diesem Kurs frischen die Teilnehmenden ihre Grundkenntnisse der spanischen Sprache auf. Sie wiederholen die Grammatik sowie die grundlegenden Wörter und Redewendungen, mit denen sie einfache Alltags- und Begegnungssituationen meistern können. Neben der Vermittlung der Sprache werden auch landeskundliche Aspekte behandelt. So bekommen die Teilnehmenden interessante Einblicke in die Geschichte, die Kultur, die Traditionen und die Mentalität der spanischsprachigen Länder.', 'https://www.vhs-karlsruhe-land.de/programm/sprachen/kw/bereich/kursdetails/kurs/L422H024SH/kursname/Spanisch A12 - Wiederholung Teil 3/kategorie-id/3', '27fa295ad6c34968e867256b01d8b376e97be047457cd6c0a4ba59b2650af3a1', '2026-04-26 14:42:06');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (35716, 'https://www.vhs-karlsruhe-land.de/standorte/stutensee/', 'RückenschuleFrauen', '2026-06-11', NULL, '09:00 - 10:00', 'Spöck, Vereinsheim TV, Spiegelsaal Steinbückelstraße 1 76297 Stutensee-Spöck', 'VHS Stutensee', 'Er trägt so manches über die Jahre, was ihm nicht gut tut: unser Rücken. Doch mit der vhs-Rückenschule tun Sie ihm wieder etwas Gutes. Lassen Sie sich zeigen, wie Ihr Rücken funktioniert, wie Sie ihn besser wahrnehmen und entspannen können. Praxisorientierte, funktionsgymnastische Übungen und anatomische sowie physiologische Grundkenntnisse helfen Ihnen in Beruf und Freizeit.', 'https://www.vhs-karlsruhe-land.de/programm/gesundheit-ernaehrung/kw/bereich/kursdetails/kurs/L302H722SH/kursname/Rueckenschule - Frauen/kategorie-id/7', 'beaebf3959e8bc7fb797af981aa1326db9cf0618b71fd64ccb3c8728497f80d7', '2026-04-26 14:42:06');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (35717, 'https://www.vhs-karlsruhe-land.de/standorte/stutensee/', 'RückenschuleFrauen', '2026-06-11', NULL, '10:05 - 11:05', 'Spöck, Vereinsheim TV, Spiegelsaal Steinbückelstraße 1 76297 Stutensee-Spöck', 'VHS Stutensee', 'Er trägt so manches über die Jahre, was ihm nicht gut tut: unser Rücken. Doch mit der vhs-Rückenschule tun Sie ihm wieder etwas Gutes. Lassen Sie sich zeigen, wie Ihr Rücken funktioniert, wie Sie ihn besser wahrnehmen und entspannen können. Praxisorientierte, funktionsgymnastische Übungen und anatomische sowie physiologische Grundkenntnisse helfen Ihnen in Beruf und Freizeit.', 'https://www.vhs-karlsruhe-land.de/programm/gesundheit-ernaehrung/kw/bereich/kursdetails/kurs/L302H729SH/kursname/Rueckenschule - Frauen/kategorie-id/7', '7565a613393110e01084f9976e95e4cc17256743c4cc37e5f911978585d8c99e', '2026-04-26 14:42:06');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (35718, 'https://www.vhs-karlsruhe-land.de/standorte/stutensee/', 'Pilates am Vormittag', '2026-06-11', NULL, '11:10 - 12:00', 'Spöck, Vereinsheim TV, Spiegelsaal Steinbückelstraße 1 76297 Stutensee-Spöck', 'VHS Stutensee', 'Das Ganzkörpertraining nach Joseph Pilates kombiniert Atemtechnik, Kraftübungen, Koordination und Stretching. Im Zentrum stehen Bauch, Hüften, Po und Rücken, die Körpermitte, im Pilates auch "Powerhouse" genannt. Pilates kräftigt, entspannt und dehnt auf sanfte Weise die tiefen Muskeln. Der Körper wird straff und geschmeidig, die Haltung aufrecht. Die Bewegungen werden sehr bewusst und mit großer Konzentration ausgeführt. Die Übungen sind sehr effektiv und zeigen rasch Erfolge. Wie intensiv das Training ist, können Sie individuell variieren. Gut für alle, die sich ein sanftes und effektives Training für den ganzen Körper wünschen. Keine Vorkenntnisse nötig! In jedem Alter geeignet!', 'https://www.vhs-karlsruhe-land.de/programm/gesundheit-ernaehrung/kw/bereich/kursdetails/kurs/L302H426SH/kursname/Pilates am Vormittag/kategorie-id/7', 'e283159bc6b038e4acb676957ac951b71aac716700d9f348df29a91d745ca8eb', '2026-04-26 14:42:06');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (35719, 'https://www.vhs-karlsruhe-land.de/standorte/stutensee/', 'Excel Aufbaukurs', '2026-07-01', NULL, '18:00 - 20:30', 'Stutensee-Spöck, Bürgerbüro, Sitzungssaal Spechaa Straße 11 76297 Stutensee', 'VHS Stutensee', 'In diesem Kurs erhalten Sie nicht nur eine theoretische Antwort auf Ihre Fragen, sondern lernen sofort umsetzbare, präzise und leicht verständliche Lösungen kennen und EXCEL professionell zu nutzen.Folgende Lehrinhalte werden vermittelt:- Datenbanken und Listen erstellen- mit der Funktion TEILERGEBISSE und SPEZIALFILTER Datentabellen auswerten- mit PIVOT-TABELLEN Statistiken, komplexe Auswertungen etc.. erstellen- mit den Spezialfunktionen wie SVERWEIS, WENN, UND/ODER Daten analysieren und Excel Entscheidungen treffen lassen.Undokumentierte Funktionen, Spezialtechniken mit hohem Nutzwert und das einfache Gewusst - wie", das ist die Mischung in dieser Schulung, in der Sie Sicherheit im Umgang mit Excel gewinnen.Teilnahmevoraussetzung:- Excel - Grundkenntnisse; sicherer Umgang mit Tastatur und Computermaus.', 'https://www.vhs-karlsruhe-land.de/programm/arbeitswelt-it/kw/bereich/kursdetails/kurs/L501H104SK/kursname/Excel Aufbaukurs/kategorie-id/5', 'a87363cbcbff402267dcbc001d8269427273807b87aa69c47da17e6742cfff10', '2026-04-26 14:42:06');
