INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (35852, 'https://meinstutensee.de/termine/', 'Ausschuss für Umwelt und Technik', '2026-05-04', '2026-05-04', '18:00', 'Bürgersaal Rathaus Stutensee', 'Stadtverwaltung Stutensee', 'Tagesordnung    Förderung Interessengemeinschaft “Asiatische Hornisse Hardt e.V.”   Bauvorhaben Waldstraße 37– Bauturbo gemäß § 246 e BauGB   Bestätigung der Sitzungsniederschrift   Bekanntgaben – Mitteilungen   Fragestunde für Stadträtinnen und Stadträte', 'https://www.meinstutensee.de/veranstaltungen/ausschuss-fuer-umwelt-und-technik/', 'e0f671972483e6022aebf9dee0a06e34d2bdd81fb8f59f72f272127b9716492b', '2026-04-28 17:50:06');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (35853, 'https://meinstutensee.de/termine/', 'Workshop für Alleinerziehende: Exit-Strategien', '2026-05-05', '2026-05-05', '15:00', '', 'Tageselternverein Bruchsal', 'In angespannten Situationen einen kühlen Kopf bewahren – mit welchen Methoden das geht, vermittelt ein Workshop in Stutensee für Alleinerziehende. Er wird durchgeführt von ACT-Beraterin Romina Tirolf. ACT steht für: Aktivierung, Coaching, Teilhabe. Eine Anmeldung ist erforderlich.   Anmeldung unter r.tirolf@tev-bruchsal.de, Telefon 07251/981987826. Bitte Anzahl und Alter der Kinder angeben, die Sie mitbringen.', 'https://www.meinstutensee.de/veranstaltungen/workshop-fuer-alleinerziehende-exit-strategien/', 'c25a675ed05f6a25f0b513de17f16a5492df88e4b953563cd5be48b1e15a9701', '2026-04-28 17:50:06');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (35854, 'https://meinstutensee.de/termine/', 'Kamishibai-Erzähltheater', '2026-05-05', '2026-05-05', '15:15', 'Stadtbibliothek Blankenloch', 'Stadtbibliothek Blankenloch', 'Im Erzähltheater geht es weiter mit „Gesucht! Henri der Bücherdieb“ von Emily MacKenzie. Die Geschichte ist für Kinder im Alter von drei bis zehn Jahren geeignet. „Henri liebt Bücher. Er muss immer mehr davon haben. Das bringt ihn leider in eine schwierige Situation. Ob Artur, der Bücher genauso sehr liebt, ihm da helfen kann?“   Der Eintritt ist frei, eine Anmeldung erforderlich und in der Regel bis zu einem Tag vor der jeweiligen Veranstaltung möglich: persönlich in der jeweiligen Stadtbibliothek / Bücherei, alternativ per Telefon 07244/969-4270 oder E-Mail an maria.toth@stutensee.de. Bitte bei Anmeldung Name, Vorname und Alter des Kindes, eine Telefonnummer und ggfs. eine Fotoerlaubnis mitteilen.', 'https://www.meinstutensee.de/veranstaltungen/kamishibai-erzaehltheater/', '5c9dcd6ee53b71e43bf06bdea920c6240005e0da2bf64a237ebe92666f626c52', '2026-04-28 17:50:06');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (35855, 'https://meinstutensee.de/termine/', 'Kamishibai-Erzähltheater', '2026-05-06', '2026-05-06', '15:30', 'Evangelisches Gemeindehaus Friedrichstal', '', 'Im Erzähltheater geht es weiter mit „Gesucht! Henri der Bücherdieb“ von Emily MacKenzie. Die Geschichte ist für Kinder im Alter von drei bis zehn Jahren geeignet. „Henri liebt Bücher. Er muss immer mehr davon haben. Das bringt ihn leider in eine schwierige Situation. Ob Artur, der Bücher genauso sehr liebt, ihm da helfen kann?“   Der Eintritt ist frei, eine Anmeldung erforderlich und in der Regel bis zu einem Tag vor der jeweiligen Veranstaltung möglich: persönlich in der jeweiligen Stadtbibliothek / Bücherei, alternativ per Telefon 07244/969-4270 oder E-Mail an maria.toth@stutensee.de. Bitte bei Anmeldung Name, Vorname und Alter des Kindes, eine Telefonnummer und ggfs. eine Fotoerlaubnis mitteilen.', 'https://www.meinstutensee.de/veranstaltungen/kamishibai-erzaehltheater-2/', '0ccb4c8f9a68d276fe3d891515d46580a04fa3d27c01d96cb9522613d27d2ada', '2026-04-28 17:50:06');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (35856, 'https://meinstutensee.de/termine/', 'Sitzung Ortschaftsrat Spöck', '2026-05-06', '2026-05-06', '19:00', 'Begegnungszentrum Regenbogen Spöck', 'Ortschaftsrat Spöck', 'Tagesordnung    Bekanntgaben   Fragestunde für Bürgerinnen und Bürger   „Wohnen im Alter“, Stadtteil Spöck– Festlegung des Festpreises   Zusatzbezeichnung für den Stadtteil Spöck   Bestätigung der Sitzungsniederschriften   Fragestunde für Ortschafts- und Stadträte', 'https://www.meinstutensee.de/veranstaltungen/sitzung-ortschaftsrat-spoeck/', '681cb69d424eb2b0a83a33a2c833c71758089f7307091f72c0fe655ae10bf31e', '2026-04-28 17:50:06');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (35857, 'https://meinstutensee.de/termine/', 'Infoveranstaltung: Asiatische Hornisse', '2026-05-07', '2026-05-07', '18:00', 'Bürgersaal Rathaus Stutensee', 'Interessensgemeinschaft Asiatische Hornisse Hardt e.V.', 'Die Asiatische Hornisse („Vespa velutina“) breitet sich seit einigen Jahren zunehmend auch in Baden-Württemberg aus. Als etablierte invasive Art ist sie eine ernstzunehmende Gefahr für unsere heimische Biodiversität. Honigbienen und andere bestäubende Insekten sind besonders betroffen. Wie lässt sich die Vespa velutina, auch im Vergleich zur europäischen Hornisse, sicher erkennen? Was ist bei Fund eines Hornissen-Nests zu tun? Dazu informiert der Verein Asiatische Hornisse Hardt e.V. am 7. Mai, 18 Uhr, im Rathaus Stutensee.', 'https://www.meinstutensee.de/veranstaltungen/infoveranstaltung-zum-thema-asiatische-hornissegegenmassnahmen-und-schutzstrategien/', '2b64668f70604fbf5f369f5fd23d5229887891b32e3d1f7a39a6baf152783483', '2026-04-28 17:50:06');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (35858, 'https://meinstutensee.de/termine/', 'Bewegung und Gesundheit und ihre Auswirkung auf Demenz', '2026-05-07', '2026-05-07', '19:00', 'Familienzentrum Friedrichstal &quot;Kult Café&quot;', '', 'Zur Anmeldung: https://www.vhs-karlsruhe-land.de/programm/gesundheit-ernaehrung/kw/bereich/kursdetails/kategorie-id/7/kurs/L300H003SL/kursname/Bewegung%20und%20Gesundheit%20und%20ihre%20Auswirkung%20auf%20Demenz%20Vortrag/warenkorb-hinzufuegen/L300H003SL/#inhalt', 'https://www.meinstutensee.de/veranstaltungen/bewegung-und-gesundheit-und-ihre-auswirkung-auf-demenz/', '157437f0bd36aee2e2b3e666d08a04807a0c1d83e9314e6268c3d0304c2f3f3e', '2026-04-28 17:50:06');
