INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (35867, 'https://meinstutensee.de/termine/', 'Kamishibai-Erzähltheater', '2026-05-20', '2026-05-20', '15:30', 'Stadtbibliothek Spöck', 'Stadtbibliothek Blankenloch', 'Im Erzähltheater geht es weiter mit „Gesucht! Henri der Bücherdieb“ von Emily MacKenzie. Die Geschichte ist für Kinder im Alter von drei bis zehn Jahren geeignet. „Henri liebt Bücher. Er muss immer mehr davon haben. Das bringt ihn leider in eine schwierige Situation. Ob Artur, der Bücher genauso sehr liebt, ihm da helfen kann?“   Der Eintritt ist frei, eine Anmeldung erforderlich und in der Regel bis zu einem Tag vor der jeweiligen Veranstaltung möglich: persönlich in der jeweiligen Stadtbibliothek / Bücherei, alternativ per Telefon 07244/969-4270 oder E-Mail an maria.toth@stutensee.de. Bitte bei Anmeldung Name, Vorname und Alter des Kindes, eine Telefonnummer und ggfs. eine Fotoerlaubnis mitteilen.', 'https://www.meinstutensee.de/veranstaltungen/kamishibai-erzaehltheater-4/', '6b7200eba0fd6ede7a7bb3b82c38b2929d5692701aa5aa89146b3a089ae6f97d', '2026-04-28 17:50:06');
