INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (35869, 'https://meinstutensee.de/termine/', 'Remember in concert', '2026-05-30', '2026-05-30', '20:00', 'Charly''s Kleinkunstbühne', 'Charly''s Kleinkunstbühne', '', 'https://www.meinstutensee.de/veranstaltungen/remember-in-concert-2/', '15a87ae4a6ddc4ee79a924d2f0c858d8047e6d5a9383644d50b57884dfa5f613', '2026-04-28 17:50:06');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (35870, 'https://meinstutensee.de/termine/', 'Vögel der Feldflur: Exkursion mit Jochen Lehmann (OAG Karlsruhe)', '2026-05-31', '2026-05-31', '07:30', 'Tennisclub Spöck', '', 'Auf einer kleinen Wanderung durch die Feldflur in Stutensee wollen wir dem Gesang von Feldlerche & Co lauschen und Arten wie Wiesenschafstelze und Schwarzkehlchen beobachten. Mit Hilfe beteiligter Landwirte konnten hier Maßnahmen wie Buntbrachen und extensive Ackerbewirtschaftung umgesetzt und der Rückgang vieler Feldvögel gestoppt werden.', 'https://www.meinstutensee.de/veranstaltungen/voegel-der-feldflur-exkursion-mit-jochen-lehmann-oag-karlsruhe/', '8df9de37d71b2c1a605bcf1d2f88b14f3aadcc1468e01f49ba5c4037f270d643', '2026-04-28 17:50:06');
