INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (36320, 'https://www.karlsdorf-neuthard.de/', 'Improvisations-Theater zum Jahresausklang', '2026-12-28', NULL, '19:30 - 22:00', 'Thomas-Morus-Heim Karlsdorf', 'Kleine Bühne Karlsdorf-Neuthard', NULL, 'https://www.karlsdorf-neuthard.de/eventcalendar?action=view_event&event_id=455', '46e2275dd099636c727e9005ad74649f2997ee4c2076f23f9fada50eab202e44', '2026-04-29 05:24:26');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (36321, 'https://www.karlsdorf-neuthard.de/', 'Jahreshauptversammlung 2026', '2026-06-25', '2026-06-25', '19:00 - 21:00', 'Zehntscheuer 1737, Kronenstraße 1, Karlsdorf-Neuthard', 'Bürgerstiftung Karlsdorf-Neuthard', 'Generalversammlung mit Berichten des Vorstands und des Kassenprüfers sowie Aussprache. Engagieren Sie sich und machen Sie von Ihrem Stimmrecht Gebrauch! Die Veranstaltung richtet sich an Vereinsmitglieder der Bürgerstiftung Karlsdorf-Neuthard e. V. Der Eintritt ist frei. Es ist keine Anmeldung erforderlich.', 'https://buergerstiftung-kn.de/event/jahreshauptversammlung-2026/', 'be0376013575baacfdb35938e658d8feae9c326753c8792761d639bc89281dd4', '2026-04-29 05:24:26');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (36322, 'https://www.karlsdorf-neuthard.de/', 'Jahresausflug 2026', '2026-06-27', '2026-06-27', '09:00 - 16:00', NULL, 'Bürgerstiftung Karlsdorf-Neuthard', 'Der diesjährige Jahresausflug führt uns in die “schönste Altstadt Deutschlands” nach Bad Wimpfen . Es erwarten uns mittelalterliches Flair, Fachwerkhäuser und die Kaiserpfalz. Ein Stadtspaziergang führt uns durch die Gassen der Altstadt und zum blauen Turm. Da dürfte für jeden was dabeisein! Die Veranstaltung richtet sich an die Vereinsangehörigen der Bürgerstiftung Karlsdorf-Neuthard e. V. Detailiertere Informationen folgen noch. “Blauer Turm Bad Wimpfen” von Rabe! , lizenziert unter CC BY-SA 3.0 .', 'https://buergerstiftung-kn.de/event/jahresausflug-2026/', 'cf0b393ad8546ffa9f71d2d02028142e637b080bddf48bc0c93155d7b6b2b905', '2026-04-29 05:24:26');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (36323, 'https://www.karlsdorf-neuthard.de/', 'lebensWERTEs: After Work Yoga', '2026-07-09', '2026-07-09', '18:30 - 19:45', 'Zehntscheuer 1737, Kronenstraße 1, Karlsdorf-Neuthard', 'Bürgerstiftung Karlsdorf-Neuthard', 'Wir freuen uns, euch zum nächsten Afterwork Yoga Event in der Zehntscheuer einladen zu können. Bitte Yogamatte und etwas Kuscheliges für die Endentspannung mitbringen. Der Kurs ist für alle Levels geeignet. Du möchtest dabei sein? Dann melde dich einfach direkt bei Juliane unter www.yuliyoga.de an. Wir freuen uns auf euch! Juliane Firnkes & das Team von LebensWERTEs der Bürgerstiftung', 'https://buergerstiftung-kn.de/event/lebenswertes-after-work-yoga/', '719ca8cb0a10644dc763b45b1132cf8e8aab5ede49750d6a171c53a4aea4230e', '2026-04-29 05:24:26');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (36324, 'https://www.karlsdorf-neuthard.de/', 'Demokratie-Workshop für Jugendliche (in Planung)', '2026-08-06', '2026-08-06', '10:00 - 17:00', 'Zehntscheuer 1737, Kronenstraße 1, Karlsdorf-Neuthard', 'Bürgerstiftung Karlsdorf-Neuthard', 'Workshop in Zusammenarbeit mit dem Lernort Kislau e. V. – Weitere Informationen folgen noch –', 'https://buergerstiftung-kn.de/event/demokratie-workshop-fuer-jugendliche/', 'b3fa786e1b882571ea174fe1409176438a91e5f353d47ca40c29cac403787abc', '2026-04-29 05:24:26');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (36325, 'https://www.karlsdorf-neuthard.de/', 'Tag des offenen Denkmals 2026 mit fürstbischöflichem Kaffeekränzchen', '2026-09-13', '2026-09-13', '13:00 - 17:00', 'Zehntscheuer 1737, Kronenstraße 1, Karlsdorf-Neuthard', 'Bürgerstiftung Karlsdorf-Neuthard', 'Am Sonntag, 13. September 2026, öffnet die historische Zehntscheuer 1737 in Karlsdorf-Neuthard von 13:00 bis 17:00 Uhr ihre Türen für den bundesweiten Tag des offenen Denkmals . Die Bürgerstiftung Karlsdorf-Neuthard e. V. lädt alle Interessierten zu einem abwechslungsreichen Nachmittag für Jung und Alt ein. Der Eintritt ist frei, eine Anmeldung ist nicht erforderlich. Besucherinnen und Besucher erwartet ein buntes Programm beim gemütlichen Beisammensein in historischem Ambiente. Es sind Führungen durch das Gebäude geplant, bei denen es Hintergrundinformationen zum Gebäude und dessen Renovierung gibt. Das „Fürstbischöfliche Kaffeekränzchen“ verspricht entspannten Austausch bei selbstgebackenen Torten und Kuchen, serviert im feinem Service.', 'https://buergerstiftung-kn.de/event/tag-des-offenen-denkmals-2026/', '617516be7b33ed7a9925902ad79c8c80e63914a73146084197583c8a56ae88e9', '2026-04-29 05:24:26');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (36326, 'https://www.karlsdorf-neuthard.de/', 'Zwiebelkuchenfest 2026', '2026-09-18', '2026-09-18', '17:00 - 22:00', 'Zehntscheuer 1737, Kronenstraße 1, Karlsdorf-Neuthard', 'Bürgerstiftung Karlsdorf-Neuthard', 'DAS stimmungsvolle Herbstfest für die ganze Familie! Am Freitag, 18. September, 17 bis 22 Uhr, steigt wieder unser traditionelles Zwiebelkuchenfest in und an der Zehntscheuer. Es gibt natürlich Zwiebelkuchen, Neuen Wein und andere ausgewählte Spezialitäten. Wie jedes Jahr sorgt eine Band mit Live-Musik und farbige Beleuchtung für ein stimmungsvolles Ambiente. Der Eintritt ist frei. Es ist keine Anmeldung erforderlich.', 'https://buergerstiftung-kn.de/event/zwiebelkuchenfest-2026/', '930321dae625a84ca813883efeca11ea6a3d1ca37d26fe8e753212ce5be7c1d7', '2026-04-29 05:24:26');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (36327, 'https://www.karlsdorf-neuthard.de/', 'lebensWERTEs: Kneipenabend 2026', '2026-10-02', '2026-10-02', '19:00 - 22:00', 'Zehntscheuer 1737, Kronenstraße 1, Karlsdorf-Neuthard', 'Bürgerstiftung Karlsdorf-Neuthard', 'Die Zehntscheuer 1737 lädt zum zweiten Kneipenabend ein! Ab 19.00 Uhr öffnen wir einen Abend lang unseren Tresen und laden herzlich dazu ein, sich mit Freunden bei uns zu treffen. Flipper, kicker, Darts und mehr warten auf unsere spielfreudigen Gäste. Der Eintritt ist frei. Es ist keine Anmeldung erforderlich.', 'https://buergerstiftung-kn.de/event/lebenswertes-kneipenabend-2026/', 'f4c2604e5237885cc7716fb6187252d6ffa540465e03b3a29890665c69ed0e60', '2026-04-29 05:24:26');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (36328, 'https://www.karlsdorf-neuthard.de/', 'KauFRAUsch Frauenflohmarkt', '2026-10-09', '2026-10-09', '19:00 - 22:00', 'Bruchbühlhalle, Bruchbühlweg 5, Karlsdorf-Neuthard', 'Bürgerstiftung Karlsdorf-Neuthard', 'Ob Jung oder Alt, ob Groß oder Klein, Hauptsache weiblich: Bei einem Gläschen Sekt und Livemusik nach Herzenslust stöbern, kaufen und quatschen. Gäste haben freien Eintritt. Die Standgebühr für VerkäuferInnen beträgt 10€. Für die Anmeldung als VerkäuferIn bitte an kauFRAUsch@buergerstiftung-kn.de wenden.', 'https://buergerstiftung-kn.de/event/kaufrausch-frauenflohmarkt-4/', '4189e1a095575c559b28ff83b6ac9fc089fc6cb46b501d6a4c94ce4a18306443', '2026-04-29 05:24:26');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (36329, 'https://www.karlsdorf-neuthard.de/', 'LIVE in der Scheuer: Konzertabend', '2026-10-16', '2026-10-16', '19:00 - 22:00', 'Zehntscheuer 1737, Kronenstraße 1, Karlsdorf-Neuthard', 'Bürgerstiftung Karlsdorf-Neuthard', 'Erleben Sie Live-Musik in der einmaligen Atmosphäre der Zehntscheuer! Musikstil und die Band werden noch bekannt gegeben. Der Eintritt ist frei. Der Hut für die Band wird herumgegeben. Es ist keine Anmeldung erforderlich.', 'https://buergerstiftung-kn.de/event/live-in-der-scheuer-konzertabend/', '1c996133f64c26cbfa38adf313135f500e6e7229029739ed2fed59a054733df1', '2026-04-29 05:24:26');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (36330, 'https://www.karlsdorf-neuthard.de/', 'lebensWERTEs: After Work Yoga', '2026-11-05', '2026-11-05', '18:30 - 19:45', 'Zehntscheuer 1737, Kronenstraße 1, Karlsdorf-Neuthard', 'Bürgerstiftung Karlsdorf-Neuthard', 'Wir freuen uns, euch zum nächsten Afterwork Yoga Event in der Zehntscheuer einladen zu können. 75 Minuten fließende Bewegungen und tiefe Entspannung. Der Kurs ist für alle Levels geeignet. Bitte eine Yogamatte und etwas Kuscheliges für die Endentspannung mitbringen. Du möchtest dabei sein? Dann melde dich einfach direkt bei Juliane unter www.yuliyoga.de an. Wir freuen uns auf euch! Juliane Firnkes & das Team von LebensWERTEs der Bürgerstiftung', 'https://buergerstiftung-kn.de/event/lebenswertes-after-work-yoga-2/', '5065e4d74dea3d3237dbf73066dc5d069e4ac0583fa99c2e37eaf13e0b51cd05', '2026-04-29 05:24:26');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (36331, 'https://www.karlsdorf-neuthard.de/', 'lebensWERTEs: Adventskranzbinden', '2026-11-26', '2026-11-26', '19:00 - 21:30', 'Zehntscheuer 1737, Kronenstraße 1, Karlsdorf-Neuthard', 'Bürgerstiftung Karlsdorf-Neuthard', 'Der 1. Advent steht vor der Türe. Deshalb bieten wir an, gemeinsam Adventskränze (Rohlinge) in der Zehntscheuer zu binden. Eine Anmeldung ist erforderlich. Genauere Informationen folgen noch. Es ist geplant, das Rohmaterial zur Verfügung zu stellen.', 'https://buergerstiftung-kn.de/event/lebenswertes-adventskranzbinden/', '53c500a10a14182088f2eace402b3e17e8154a6af0a2c3cdc5234fab6d353bc6', '2026-04-29 05:24:26');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (36332, 'https://www.karlsdorf-neuthard.de/', 'Weihnachtsfeier 2026', '2026-12-11', '2026-12-11', '19:00 - 22:00', 'Zehntscheuer 1737, Kronenstraße 1, Karlsdorf-Neuthard', 'Bürgerstiftung Karlsdorf-Neuthard', 'Der besinnlich-gesellige Jahresausklang unseres Vereins – exklusiv für alle Vereinsmitglieder der Bürgerstiftung Karlsdorf-Neuthard und die, die es noch werden wollen! Wir werden uns auch dieses Jahr etwas Besonderes für den gemeinsamen, stimmungsvollen, geselligen Abend überlegen. Was das Essen und das geplante Programm angeht, werden wir noch rechtzeitig informieren. Was wir schon mit Sicherheit wissen, ist, dass die Veranstaltung an unsere Vereinsmitglieder gerichtet ist und eine Anmeldung erforderlich sein wird. Noch kein Mitglied? Dann wird’s Zeit! Wer noch kein Mitglied ist, aber sich eh mit dem Gedanken trägt, der kann natürlich noch rechtzeitig beitreten und dann an der diesjährigen Weihnachtsfeier schon teilnehmen. Die Mitgliedserklärung zum Herunterladen gibt es auf der Startseite unserer Homepage ganz unten. Wir freuen uns auf dich und auf einen weiteren stimmungsvollen Abend in der Zehntscheuer!', 'https://buergerstiftung-kn.de/event/weihnachtsfeier-2026/', '421d3ab84820bb8782e16fa927c17e5f87f51c3231e025fe5810ba89ad782098', '2026-04-29 05:24:26');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (36333, 'https://www.bv-waldstadt.de/', 'Jahreshauptversammlung - Einladung an alle Bürgerinnen und Bürger der Waldstadt', '2026-05-20', NULL, '19:00 Uhr', 'Gemeindesaal St. Hedwig, Königsberger Str. 55, 76139 Karlsruhe', 'Bürgerverein Waldstadt e.V.', 'Einladung zur Jahreshauptversammlung am Mittwoch, 20. Mai 2026, 19.00 Uhr Gemeindesaal St. Hedwig, Königsberger Str. 55, 76139 Karlsruhe', 'https://www.bv-waldstadt.de/site/assets/files/2144/einladung_mv_2026_wb.pdf', '9fff3a32476c92e8cbae4404cd50b074251356a91603b01e572e33d7a9d1233c', '2026-04-29 05:24:28');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (36334, 'https://www.bv-waldstadt.de/', 'Einladung zur Jahreshauptversammlung am 20. Mai 2026', '2026-05-20', NULL, '19:00 Uhr', 'Waldstadt, Karlsruhe', 'Bürgerverein Waldstadt e.V.', 'Einladung zur Jahreshauptversammlung am Mittwoch, 20. Mai 2026, 19.00 Uhr Gemeindesaal St. Hedwig, Königsberger Str. 55, 76139 Karlsruhe Tagesordnung: TOP 1. Eröffnung und Begrüßung TOP 2. Geschäftsbericht 2025 TOP 3. Kassenbericht TOP 4. Bericht der Kassenprüfer TOP 5. Aussprache über die Berichte TOP 6. Entlastung des Vorstandes TOP 7. Kurzbericht zum Stand und der Perspektive des Fächerbads TOP 8. Status im sozialen Bereich und Perspektive für soziale Projekte (BM Yvette Melchien) TOP 9. Erle', 'https://www.bv-waldstadt.de/', '43c719b18a1b0a373472153e15cad5b3bab8a9ad9f13d45abe5f57866abe9188', '2026-04-29 05:24:28');
