INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (41260, 'https://meinstutensee.de/termine/', 'KulturenTreff Spöck zur Raupe Nimmersatt', '2026-05-04', '2026-05-04', '16:00', 'Begegnungszentrum Regenbogen Spöck', 'Begegnungszentrum Regenbogen Spöck', 'Einmal im Monat an einem Montag findet der KulturenTreff in Spöck im Begegnungszentrum Regenbogen statt. Egal, woher Sie kommen, Sie sind willkommen, Du bist willkommen! Was erwartet uns im Mai? Wir erleben die Raupe Nimmersatt im Buch und gebastelt wird auch. Seid Ihr dabei?   Der KulturenTreff – ein Ort für alle. Zum Hingehen. Zum Menschen treffen. Zum Ankommen. Eine Kooperation der Flüchtlingshilfe Stutensee e.V., des Begegnungszentrums Regenbogen Spöck und der Stadt Stutensee. Gefördert aus Mitteln für kommunale und ehrenamtliche Integrationsarbeit des Landratsamts Karlsruhe.', 'https://www.meinstutensee.de/veranstaltungen/kulturentreff-spoeck-zur-raupe-nimmersatt/', 'a8e318772ae93829275e7ba19c46d1db7fbfb0c3fbcf706fecf7a4d7a4ae4f51', '2026-05-01 06:41:16');
