INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (41286, 'https://meinstutensee.de/termine/', 'Jubiläumskonzert „15 Jahre Tafel Stutensee“', '2026-07-29', '2026-07-29', '18:00', 'Tafel Stutensee', 'Tafel Stutensee', 'mit dem Trio Sonido und Sängerin Colette Sternberg. Das Ensemble präsentiert ein abwechslungsreiches Programm aus Chansons, Musette-Walzern sowie internationalen Klassikern und entführt musikalisch nach Frankreich, Spanien und Italien. Anmeldung über integration@stutensee.de oder telefonisch unter 07244/969-4210.', 'https://www.meinstutensee.de/veranstaltungen/jubilaeumskonzert-15-jahre-tafel-stutensee/', '39a848a57b95652b0115014007d6f60dc19e18428e67405f665ca990f5f4bb2a', '2026-05-01 06:41:16');
