INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (72551, 'https://rintheim-bv.de', '100 Jahre Kath. Gemeinde Rintheim', '2026-05-03', NULL, '', 'Karlsruhe-Rintheim', 'Bürgerverein Rintheim', '„Feste soll man so feiern, wie sie fallen“ – darum wird am 03. Mai 2026 das 100-jährige Bestehen der Katholischen Gemeinde St. Martin Rintheim mit einem festlichen Gottesdienst um 11 Uhr und anschließendem Empfang gefeiert. Dazu sind Alle herzlich eingeladen. Am 1. Mai 1926 errichtete das Erzbischöf', 'https://www.rintheim-bv.de/?p=5256', '96f95db9501ceb04614936b8a4f2b3cf0791bb6196683f72d7dccdaa55bf561f', '2026-05-01 21:11:18');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (72552, 'https://rintheim-bv.de', 'JHV mit Neuwahlen', '2026-05-06', NULL, '19:00', 'Karlsruhe-Rintheim', 'Bürgerverein Rintheim', 'Liebe Mitglieder, Sie sind herzlich eingeladen zur Jahreshauptversammlung am 6. Mai 2026 um 19 Uhr im den „Rintheimer Stuben“ beim TSV. Die Einladung sollten Sie bereits per eMail oder über unser Bürgerheft erhalten haben. Neben dem Bericht des Vorstands stehen auch Neuwahlen an, daher freuen wir un', 'https://www.rintheim-bv.de/?p=5238', 'd7dfe6794d1baab53c1c3adb66d9e1c76f3f3161be1bd57923be98e79df4d39d', '2026-05-01 21:11:18');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (72553, 'https://rintheim-bv.de', 'Kippen Picken', '2026-05-11', NULL, '14:00–16:00', 'Karlsruhe-Rintheim', 'Bürgerverein Rintheim', 'Wir treffen uns mit den City Cleaners Karlsruhe am 11.5.2026 um 14 Uhr an der Endhaltestelle der Straßenbahn in Rintheim zum gemeinsamen Kippen Picken. Machen Sie mit? Bringen Sie bitte gute Laune und ein paar Arbeitshandschuhe mit. Wir sorgen für Zangen und Behältnisse zum Einsammeln. Wenn man weiß', 'https://www.rintheim-bv.de/?p=5192', '30415ebd2ef3312ebf61dbf332a7193afcbb00c4595d58cc529b41d99cfb2019', '2026-05-01 21:11:18');
INSERT INTO raw_events (id, source_url, title, date_start, date_end, time_raw, location, organizer, description, event_url, raw_html_hash, scraped_at) VALUES (72554, 'https://rintheim-bv.de', '„Offene Pforte“ – Mitmach-Garten lädt zur Besichtigung ein', '2026-05-09', NULL, '14:00–18:00', 'Karlsruhe-Rintheim', 'Bürgerverein Rintheim', 'Das Gartenbauamt der Stadt Karlsruhe organisiert auch dieses Jahr wieder die Veranstaltungsreihe „Offene Pforte“ und bietet allen Gartenliebhabern eine Plattform für Austausch, Pflanzentausch und Wissenstransfer. Dabei steht nicht die Perfektion im Vordergrund, sondern die Vielfalt der verschiedenen', 'https://www.rintheim-bv.de/?p=5233', 'ca1620569ce90c179f7851ba1e2e0d93e8ef2d65c1ef5a83b98a0703c1141a09', '2026-05-01 21:11:18');
