INSERT INTO curated_events (id, title, normalized_title, date_start, date_end, time_raw, location, organizer, description, event_url, sources, tags, recurring_group_id, dedup_round, created_at, updated_at) VALUES (206075, 'Englisch B1.1 (Teil 5)', NULL, '2026-05-05', NULL, '19:00 - 20:30', 'Blankenloch, Altes Rathaus Hauptstraße 80 76297 Stutensee-Blankenloch', 'VHS Stutensee', 'In diesem Kurs bauen die Teilnehmenden ihre Grundkenntnisse der englischen Sprache und Kultur aus. Sie lernen es insbesondere, sich in den verschiedensten alltäglichen Situationen zu verständigen ebenso wie über gegenwärtige und vergangene Erlebnisse und über Vorhaben in der nahen Zukunft zu berichten. Dabei erweitern sie ihren Wortschatz und ihre mündlichen Ausdrucksfähigkeiten. Neben der Vermittlung der Sprache werden auch landeskundliche Aspekte behandelt. So bekommen die Teilnehmenden weitere interessante Einblicke in die Geschichte, die Kultur, die Traditionen und die Mentalität der englischsprachigen Länder.', 'https://www.vhs-karlsruhe-land.de/programm/sprachen/kw/bereich/kursdetails/kurs/L406H013SH/kursname/Englisch B11 Teil 5/kategorie-id/3', 'https://www.vhs-karlsruhe-land.de/standorte/stutensee/', 'Sport,Kultur,Blankenloch', NULL, NULL, '2026-05-03 10:53:21', '2026-05-03 10:53:21');
