INSERT INTO curated_events (id, title, normalized_title, date_start, date_end, time_raw, location, organizer, description, event_url, sources, tags, recurring_group_id, dedup_round, created_at, updated_at) VALUES (206094, 'JHV mit Neuwahlen', NULL, '2026-05-06', NULL, '19:00', 'Karlsruhe-Rintheim', 'Bürgerverein Rintheim', 'Liebe Mitglieder, Sie sind herzlich eingeladen zur Jahreshauptversammlung am 6. Mai 2026 um 19 Uhr im den „Rintheimer Stuben“ beim TSV. Die Einladung sollten Sie bereits per eMail oder über unser Bürgerheft erhalten haben. Neben dem Bericht des Vorstands stehen auch Neuwahlen an, daher freuen wir un', 'https://www.rintheim-bv.de/?p=5238', 'https://rintheim-bv.de', 'Sport,Musik,Rintheim', NULL, NULL, '2026-05-03 10:53:21', '2026-05-03 10:53:21');
INSERT INTO curated_events (id, title, normalized_title, date_start, date_end, time_raw, location, organizer, description, event_url, sources, tags, recurring_group_id, dedup_round, created_at, updated_at) VALUES (206096, 'Kamishibai-Erzähltheater', NULL, '2026-05-06', '2026-05-06', '15:30', 'Evangelisches Gemeindehaus Friedrichstal', '', 'Im Erzähltheater geht es weiter mit „Gesucht! Henri der Bücherdieb“ von Emily MacKenzie. Die Geschichte ist für Kinder im Alter von drei bis zehn Jahren geeignet. „Henri liebt Bücher. Er muss immer mehr davon haben. Das bringt ihn leider in eine schwierige Situation. Ob Artur, der Bücher genauso sehr liebt, ihm da helfen kann?“   Der Eintritt ist frei, eine Anmeldung erforderlich und in der Regel bis zu einem Tag vor der jeweiligen Veranstaltung möglich: persönlich in der jeweiligen Stadtbibliothek / Bücherei, alternativ per Telefon 07244/969-4270 oder E-Mail an maria.toth@stutensee.de. Bitte bei Anmeldung Name, Vorname und Alter des Kindes, eine Telefonnummer und ggfs. eine Fotoerlaubnis mitteilen.', 'https://www.meinstutensee.de/veranstaltungen/kamishibai-erzaehltheater-2/', 'https://meinstutensee.de/termine/', 'Kultur,Kinder,Friedrichstal', NULL, NULL, '2026-05-03 10:53:21', '2026-05-03 10:53:21');
INSERT INTO curated_events (id, title, normalized_title, date_start, date_end, time_raw, location, organizer, description, event_url, sources, tags, recurring_group_id, dedup_round, created_at, updated_at) VALUES (206097, 'Krabbelgruppe im ev. Gemeindehaus Staffort', NULL, '2026-05-06', '2026-05-06', '09:30', 'Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297', 'Kirchengemeinde Staffort-Büchenau', 'Bist du im Alter von 0 bis 3 Jahren?
Dann komm doch zum…

… Spielen
… Singen
… Freunde finden
… Basteln und Malen
… Feste feiern
und weitere Aktionen in die Krabbelgruppe.

Wir freuen uns auf dich!

Ansprechpartner: Janine Kirchner', 'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2026-05-06/', 'https://stutenseekinderkalender.de', 'Musik,Kultur,Staffort,Büchenau', 206097, NULL, '2026-05-03 10:53:21', '2026-05-03 10:53:21');
