INSERT INTO curated_events (id, title, normalized_title, date_start, date_end, time_raw, location, organizer, description, event_url, sources, tags, recurring_group_id, dedup_round, created_at, updated_at) VALUES (206110, 'Eltern-Kind-Treff ''Frühe Hilfen''', NULL, '2026-05-07', NULL, '10:15-11:45', 'Mehrgenerationenhaus Bürgerwerkstatt Stutensee, Seegrabenweg 5, Stutensee', 'Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.', 'Für Eltern mit Kindern von 0-2 Jahren unter Leitung einer Sozialpädagogin', 'https://www.buergerwerkstatt-stutensee.de/', 'https://www.buergerwerkstatt-stutensee.de/', 'Kinder,Treff,Blankenloch', NULL, NULL, '2026-05-03 10:53:21', '2026-05-03 11:04:00');
INSERT INTO curated_events (id, title, normalized_title, date_start, date_end, time_raw, location, organizer, description, event_url, sources, tags, recurring_group_id, dedup_round, created_at, updated_at) VALUES (206111, 'Eltern-Kind-Treff „Frühe Hilfen“', NULL, '2026-05-07', '2026-05-07', '10:15', 'Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297', 'Frühe Hilfen Landkreis Karlsruhe', 'Einmal im Monat treffen sich Mütter und Väter mit ihren Kindern im Alter von 0 – 2 Jahren unter der Leitung einer Sozialpädagogin.
Die Treffen bieten Raum sich mit anderen Eltern auszutauschen und Fragen und Anliegen mit der pädagogischen Gruppenleitung zu besprechen. Sie erfahren Interessantes zu verschiedenen Themen rund um die Erziehung und Entwicklung und erhalten Spiel- und Beschäftigungsanregungen. Die Kinder haben währenddessen Zeit zum Spielen und Entdecken.

12.03.2026 Von (Ab)stillen bis Zeckenschutz – Offene Fragerunde mit der Familienhebamme
16.04.2026 Kommunikation mit Kindern unter 3 Jahren
07.05.2026 Trageberatung
11.06.2026 Umgang mit Medien Frau Bock
02.07.2026 Sicher im Auto

Die Teilnahme ist kostenlos.
Eine Anmeldung ist erwünscht.
Flyer Eltern-Kind-Treff Frühe Hilfen 2026', 'https://stutenseekinderkalender.de/event/eltern-kind-treff-fruehe-hilfen/2026-05-07/', 'https://stutenseekinderkalender.de', 'Kinder,Essen,Blankenloch', NULL, NULL, '2026-05-03 10:53:21', '2026-05-03 10:53:21');
INSERT INTO curated_events (id, title, normalized_title, date_start, date_end, time_raw, location, organizer, description, event_url, sources, tags, recurring_group_id, dedup_round, created_at, updated_at) VALUES (206112, 'Ganzheitliche Schwangerschaftsgymnastik', NULL, '2026-05-07', '2026-05-07', '17:00', 'Sporthalle, Heinrich-Heine-Straße 1, Stutensee-Spöck, 76297', 'vhs Karlsruhe Land', 'Eine Schwangerschaft ist immer etwas Einzigartiges und Besonderes. Der Körper stellt sich um, bereitet sich auf die kommenden Wochen und Monaten vor und verändert sich.
Um die bevorstehenden Veränderungen für dich und dein Kind positiv zu unterstützen, zeige ich dir im Kurs angepasste Kraftübungen, die deinen Körper ganzheitlich kräftigen sowie fit halten. Zudem minimieren wir gemeinsam mit speziellen Entspannungseinheiten Beschwerden wie Rückenschmerzen, Beckenbodenschwäche oder auftretende Wachstumsschmerzen.
Im Kurs kläre ich dich zudem auf, welche Veränderungen dein Körper in den kommenden Schwangerschaftswochen durchlaufen wird und wie du deinen Alltag optimal anpassen kannst.
Ein Austausch über deine Wunschthemen und Fragen sind herzlich willkommen!
Du kannst den Kurs beim Wohlergehen bis zum Ende der Schwangerschaft besuchen.
Bitte mitbringen: Bequeme Kleidung, Turnschuhe, Getränk.
Kursgebühr: 33,00 €
Bei folgenden Punkten bitte erst deine(n) Frauenarzt/Frauenärztin konsultieren und die Kursteilnahme abklären lassen:
– Risikoschwangerschaft
– Bluthochdruck
– Schwangerschaftsdiabetes
Geschwisterkinder können mitgebracht werden. Es werden Spielmöglichkeiten bereitgestellt.
', 'https://stutenseekinderkalender.de/event/ganzheitliche-schwangerschaftsgymnastik-2/2026-05-07/', 'https://stutenseekinderkalender.de', 'Sport,Kinder,Spöck', 206112, NULL, '2026-05-03 10:53:21', '2026-05-03 10:53:21');
INSERT INTO curated_events (id, title, normalized_title, date_start, date_end, time_raw, location, organizer, description, event_url, sources, tags, recurring_group_id, dedup_round, created_at, updated_at) VALUES (206113, 'Infoveranstaltung: Asiatische Hornisse', NULL, '2026-05-07', NULL, '18:00', 'Bürgersaal Rathaus Stutensee', 'Interessensgemeinschaft Asiatische Hornisse Hardt e.V.', 'Informationsveranstaltung zur Asiatischen Hornisse', 'https://www.meinstutensee.de/veranstaltungen/infoveranstaltung-asiatische-hornisse/', 'https://www.meinstutensee.de/,https://meinstutensee.de/termine/', 'Bildung,Natur', NULL, NULL, '2026-05-03 10:53:21', '2026-05-03 10:53:21');
