INSERT INTO curated_events (id, title, normalized_title, date_start, date_end, time_raw, location, organizer, description, event_url, sources, tags, recurring_group_id, dedup_round, created_at, updated_at) VALUES (206222, 'Krabbelgruppe Stutensee-Blankenloch', NULL, '2026-05-14', '2026-05-14', '09:30', 'Ev. Gemeindehaus Stutensee, Gymnasiumstraße 27, Stutensee, 76297', 'Michaelisgemeinde Blankenloch', 'Die Krabbelgruppe in Blankenloch wird von Feli und Natalie ehrenamtlich geleitet. Als Mütter von jeweils zwei Kindern im Alter von 0 bis 4 Jahren geben sie ihre Erfahrungen weiter und schaffen einen Raum für Austausch und Gemeinschaft.
