INSERT INTO curated_events (id, title, normalized_title, date_start, date_end, time_raw, location, organizer, description, event_url, sources, tags, recurring_group_id, dedup_round, created_at, updated_at) VALUES (206289, 'Kamishibai-Erzähltheater', NULL, '2026-05-20', '2026-05-20', '15:30', 'Stadtbibliothek Spöck', 'Stadtbibliothek Blankenloch', 'Im Erzähltheater geht es weiter mit „Gesucht! Henri der Bücherdieb“ von Emily MacKenzie. Die Geschichte ist für Kinder im Alter von drei bis zehn Jahren geeignet. „Henri liebt Bücher. Er muss immer mehr davon haben. Das bringt ihn leider in eine schwierige Situation. Ob Artur, der Bücher genauso sehr liebt, ihm da helfen kann?“   Der Eintritt ist frei, eine Anmeldung erforderlich und in der Regel bis zu einem Tag vor der jeweiligen Veranstaltung möglich: persönlich in der jeweiligen Stadtbibliothek / Bücherei, alternativ per Telefon 07244/969-4270 oder E-Mail an maria.toth@stutensee.de. Bitte bei Anmeldung Name, Vorname und Alter des Kindes, eine Telefonnummer und ggfs. eine Fotoerlaubnis mitteilen.', 'https://www.meinstutensee.de/veranstaltungen/kamishibai-erzaehltheater-4/', 'https://meinstutensee.de/termine/', 'Kultur,Kinder,Blankenloch,Spöck', NULL, NULL, '2026-05-03 10:53:21', '2026-05-03 10:53:21');
