INSERT INTO curated_events (id, title, normalized_title, date_start, date_end, time_raw, location, organizer, description, event_url, sources, tags, recurring_group_id, dedup_round, created_at, updated_at) VALUES (206300, 'Ganzheitliche Schwangerschaftsgymnastik', NULL, '2026-05-21', '2026-05-21', '17:00', 'Sporthalle, Heinrich-Heine-Straße 1, Stutensee-Spöck, 76297', 'vhs Karlsruhe Land', 'Eine Schwangerschaft ist immer etwas Einzigartiges und Besonderes. Der Körper stellt sich um, bereitet sich auf die kommenden Wochen und Monaten vor und verändert sich.
Um die bevorstehenden Veränderungen für dich und dein Kind positiv zu unterstützen, zeige ich dir im Kurs angepasste Kraftübungen, die deinen Körper ganzheitlich kräftigen sowie fit halten. Zudem minimieren wir gemeinsam mit speziellen Entspannungseinheiten Beschwerden wie Rückenschmerzen, Beckenbodenschwäche oder auftretende Wachstumsschmerzen.
Im Kurs kläre ich dich zudem auf, welche Veränderungen dein Körper in den kommenden Schwangerschaftswochen durchlaufen wird und wie du deinen Alltag optimal anpassen kannst.
Ein Austausch über deine Wunschthemen und Fragen sind herzlich willkommen!
Du kannst den Kurs beim Wohlergehen bis zum Ende der Schwangerschaft besuchen.
Bitte mitbringen: Bequeme Kleidung, Turnschuhe, Getränk.
Kursgebühr: 33,00 €
Bei folgenden Punkten bitte erst deine(n) Frauenarzt/Frauenärztin konsultieren und die Kursteilnahme abklären lassen:
– Risikoschwangerschaft
– Bluthochdruck
– Schwangerschaftsdiabetes
Geschwisterkinder können mitgebracht werden. Es werden Spielmöglichkeiten bereitgestellt.
', 'https://stutenseekinderkalender.de/event/ganzheitliche-schwangerschaftsgymnastik-2/2026-05-21/', 'https://stutenseekinderkalender.de', 'Sport,Kinder,Spöck', 206112, NULL, '2026-05-03 10:53:21', '2026-05-03 10:53:21');
INSERT INTO curated_events (id, title, normalized_title, date_start, date_end, time_raw, location, organizer, description, event_url, sources, tags, recurring_group_id, dedup_round, created_at, updated_at) VALUES (206301, 'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)', NULL, '2026-05-21', '2026-05-21', '18:30', 'DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297', 'DRK Blankenloch e.V.', 'Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.
Interessierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.', 'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2026-05-21/', 'https://stutenseekinderkalender.de', 'Kinder,Workshop,Blankenloch', 206114, NULL, '2026-05-03 10:53:21', '2026-05-03 10:53:21');
