INSERT INTO curated_events (id, title, normalized_title, date_start, date_end, time_raw, location, organizer, description, event_url, sources, tags, recurring_group_id, dedup_round, created_at, updated_at) VALUES (206364, 'Fit in der Schwangerschaft', NULL, '2026-05-29', '2026-05-29', '09:00', 'Mamawerk, Kirchstraße 9, Stutensee-Spöck, 76297', 'Mamawerk', 'Übungen die auf die Schwangerschaft zugeschnitten sind, halten dich fit und bereiten auf die Geburt vor. Dein Beckenboden wird gestärkt, um auch nach der Geburt standfest zu bleiben. In einer kleinen Gruppe aktivieren und mobilisieren wir deinen Körper. Außerdem informiere ich dich rund um das Thema Schwangerschaft und Sport.
