INSERT INTO curated_events (id, title, normalized_title, date_start, date_end, time_raw, location, organizer, description, event_url, sources, tags, recurring_group_id, dedup_round, created_at, updated_at) VALUES (206438, 'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern', NULL, '2026-06-09', '2026-06-09', '19:00', 'Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297', 'Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus', 'Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.
Die Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.
Hinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.

Jeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)
Kostenfrei

Anmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)', 'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2026-06-09/', 'https://stutenseekinderkalender.de', 'Kinder,Handwerk,Friedrichstal', 206085, NULL, '2026-05-03 10:53:21', '2026-05-03 10:53:21');
INSERT INTO curated_events (id, title, normalized_title, date_start, date_end, time_raw, location, organizer, description, event_url, sources, tags, recurring_group_id, dedup_round, created_at, updated_at) VALUES (206439, 'Spanisch A1.2 - Wiederholung (Teil 3)', NULL, '2026-06-09', NULL, '18:00 - 19:30', 'Blankenloch, Altes Rathaus, Raum 1.3 Hauptstraße 80 76297 Stutensee-Blankenloch', 'VHS Stutensee', 'In diesem Kurs frischen die Teilnehmenden ihre Grundkenntnisse der spanischen Sprache auf. Sie wiederholen die Grammatik sowie die grundlegenden Wörter und Redewendungen, mit denen sie einfache Alltags- und Begegnungssituationen meistern können. Neben der Vermittlung der Sprache werden auch landeskundliche Aspekte behandelt. So bekommen die Teilnehmenden interessante Einblicke in die Geschichte, die Kultur, die Traditionen und die Mentalität der spanischsprachigen Länder.', 'https://www.vhs-karlsruhe-land.de/programm/sprachen/kw/bereich/kursdetails/kurs/L422H024SH/kursname/Spanisch A12 - Wiederholung Teil 3/kategorie-id/3', 'https://www.vhs-karlsruhe-land.de/standorte/stutensee/', 'Sport,Kultur,Blankenloch', NULL, NULL, '2026-05-03 10:53:21', '2026-05-03 10:53:21');
