INSERT INTO curated_events (id, title, normalized_title, date_start, date_end, time_raw, location, organizer, description, event_url, sources, tags, recurring_group_id, dedup_round, created_at, updated_at) VALUES (206456, 'Jugendrotkreuz – Gruppe „Dinos“ (12-17 Jahre)', NULL, '2026-06-11', '2026-06-11', '18:30', 'DRK Blankenloch e.V., Gymnasiumstraße 14A, Stutensee-Blankenloch, 76297', 'DRK Blankenloch e.V.', 'Im Jugendrotkreuz lernen Kinder und Jugendliche spielerisch und altersgerecht Erste Hilfe, Sicherheit im Alltag und Gemeinschaftssinn. Die Treffen finden wöchentlich donnerstags statt und bieten spannende Übungen, Ausflüge und Aktionen. Ein tolles Angebot für junge Menschen, die helfen möchten oder einfach neugierig sind, wie man sich einbringen kann.
Interessierte sind jederzeit willkommen! Einfach vorbeischauen oder Kontakt aufnehmen über die Webseite des Ortsvereins.', 'https://stutenseekinderkalender.de/event/jugendrotkreuz-gruppe-dinos-12-17-jahre/2026-06-11/', 'https://stutenseekinderkalender.de', 'Kinder,Workshop,Blankenloch', 206114, NULL, '2026-05-03 10:53:21', '2026-05-03 10:53:21');
