INSERT INTO curated_events (id, title, normalized_title, date_start, date_end, time_raw, location, organizer, description, event_url, sources, tags, recurring_group_id, dedup_round, created_at, updated_at) VALUES (206463, 'RückenschuleFrauen', NULL, '2026-06-11', NULL, '09:00 - 10:00', 'Spöck, Vereinsheim TV, Spiegelsaal Steinbückelstraße 1 76297 Stutensee-Spöck', 'VHS Stutensee', 'Er trägt so manches über die Jahre, was ihm nicht gut tut: unser Rücken. Doch mit der vhs-Rückenschule tun Sie ihm wieder etwas Gutes. Lassen Sie sich zeigen, wie Ihr Rücken funktioniert, wie Sie ihn besser wahrnehmen und entspannen können. Praxisorientierte, funktionsgymnastische Übungen und anatomische sowie physiologische Grundkenntnisse helfen Ihnen in Beruf und Freizeit.', 'https://www.vhs-karlsruhe-land.de/programm/gesundheit-ernaehrung/kw/bereich/kursdetails/kurs/L302H722SH/kursname/Rueckenschule - Frauen/kategorie-id/7', 'https://www.vhs-karlsruhe-land.de/standorte/stutensee/', 'Kinder,Bildung,Spöck', NULL, NULL, '2026-05-03 10:53:21', '2026-05-03 10:53:21');
