INSERT INTO curated_events (id, title, normalized_title, date_start, date_end, time_raw, location, organizer, description, event_url, sources, tags, recurring_group_id, dedup_round, created_at, updated_at) VALUES (206472, 'Eltern-Baby-Treff', NULL, '2026-06-12', '2026-06-12', '09:30', 'Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297', 'Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus', '
In dieser offenen Krabbelgruppe können Eltern und Kinder gemeinsam spielen, singen und entdecken. Die Treffen bieten Raum für Bewegung, kreative Spiele und Austausch in entspannter Atmosphäre. Auch spontane Teilnahme ist möglich – ohne Anmeldung und kostenfrei.


Jeden Freitag 9:30 – 11:00 Uhr
Für Eltern mit Kindern von 0 bis 3 Jahren.

Kontakt:Corinna Konrad corinnakonrad@gmx.de oder 01725618123 (Vertretung: Christine Berger)
Bei schönem Wetter finden gelegentlich Treffen im Freien oder kleine Ausflüge statt.
Hinweis:Die Informationen im Kalender werden teilweise automatisch übernommen und können daher unvollständig oder nicht mehr aktuell sein. Bitte überprüft die Angaben direkt auf der Webseite des Veranstalters oder kontaktiert ihn bei Fragen.', 'https://stutenseekinderkalender.de/event/eltern-baby-treff/2026-06-12/', 'https://stutenseekinderkalender.de', 'Sport,Musik,Friedrichstal', 206128, NULL, '2026-05-03 10:53:21', '2026-05-03 10:53:21');
INSERT INTO curated_events (id, title, normalized_title, date_start, date_end, time_raw, location, organizer, description, event_url, sources, tags, recurring_group_id, dedup_round, created_at, updated_at) VALUES (206473, 'Fit in der Schwangerschaft', NULL, '2026-06-12', '2026-06-12', '09:00', 'Mamawerk, Kirchstraße 9, Stutensee-Spöck, 76297', 'Mamawerk', 'Übungen die auf die Schwangerschaft zugeschnitten sind, halten dich fit und bereiten auf die Geburt vor. Dein Beckenboden wird gestärkt, um auch nach der Geburt standfest zu bleiben. In einer kleinen Gruppe aktivieren und mobilisieren wir deinen Körper. Außerdem informiere ich dich rund um das Thema Schwangerschaft und Sport.
Der Kurs hat 8 Termine Die maximale Teilnehmerzahl beträgt 10 Teilnehmerinnen.
Voraussetzungen: Dein Frauenarzt sollte dir vorab eine komplikationslose Schwangerschaft bestätigen und dir Bescheinigen, dass leichter Sport getätigt werden darf.
 ', 'https://stutenseekinderkalender.de/event/fit-in-der-schwangerschaft/2026-06-12/', 'https://stutenseekinderkalender.de', 'Sport,Fest,Spöck', 206131, NULL, '2026-05-03 10:53:21', '2026-05-03 10:53:21');
