INSERT INTO curated_events (id, title, normalized_title, date_start, date_end, time_raw, location, organizer, description, event_url, sources, tags, recurring_group_id, dedup_round, created_at, updated_at) VALUES (206665, 'Excel Aufbaukurs', NULL, '2026-07-01', NULL, '18:00 - 20:30', 'Stutensee-Spöck, Bürgerbüro, Sitzungssaal Spechaa Straße 11 76297 Stutensee', 'VHS Stutensee', 'In diesem Kurs erhalten Sie nicht nur eine theoretische Antwort auf Ihre Fragen, sondern lernen sofort umsetzbare, präzise und leicht verständliche Lösungen kennen und EXCEL professionell zu nutzen.Folgende Lehrinhalte werden vermittelt:- Datenbanken und Listen erstellen- mit der Funktion TEILERGEBISSE und SPEZIALFILTER Datentabellen auswerten- mit PIVOT-TABELLEN Statistiken, komplexe Auswertungen etc.. erstellen- mit den Spezialfunktionen wie SVERWEIS, WENN, UND/ODER Daten analysieren und Excel Entscheidungen treffen lassen.Undokumentierte Funktionen, Spezialtechniken mit hohem Nutzwert und das einfache Gewusst - wie", das ist die Mischung in dieser Schulung, in der Sie Sicherheit im Umgang mit Excel gewinnen.Teilnahmevoraussetzung:- Excel - Grundkenntnisse; sicherer Umgang mit Tastatur und Computermaus.', 'https://www.vhs-karlsruhe-land.de/programm/arbeitswelt-it/kw/bereich/kursdetails/kurs/L501H104SK/kursname/Excel Aufbaukurs/kategorie-id/5', 'https://www.vhs-karlsruhe-land.de/standorte/stutensee/', 'Workshop,Bildung,Spöck', NULL, NULL, '2026-05-03 10:53:21', '2026-05-03 10:53:21');
