INSERT INTO curated_events (id, title, normalized_title, date_start, date_end, time_raw, location, organizer, description, event_url, sources, tags, recurring_group_id, dedup_round, created_at, updated_at) VALUES (207160, 'Tag des offenen Denkmals 2026 mit fürstbischöflichem Kaffeekränzchen', NULL, '2026-09-13', '2026-09-13', '13:00 - 17:00', 'Zehntscheuer 1737, Kronenstraße 1, Karlsdorf-Neuthard', 'Bürgerstiftung Karlsdorf-Neuthard', 'Am Sonntag, 13. September 2026, öffnet die historische Zehntscheuer 1737 in Karlsdorf-Neuthard von 13:00 bis 17:00 Uhr ihre Türen für den bundesweiten Tag des offenen Denkmals . Die Bürgerstiftung Karlsdorf-Neuthard e. V. lädt alle Interessierten zu einem abwechslungsreichen Nachmittag für Jung und Alt ein. Der Eintritt ist frei, eine Anmeldung ist nicht erforderlich. Besucherinnen und Besucher erwartet ein buntes Programm beim gemütlichen Beisammensein in historischem Ambiente. Es sind Führungen durch das Gebäude geplant, bei denen es Hintergrundinformationen zum Gebäude und dessen Renovierung gibt. Das „Fürstbischöfliche Kaffeekränzchen“ verspricht entspannten Austausch bei selbstgebackenen Torten und Kuchen, serviert im feinem Service.', 'https://buergerstiftung-kn.de/event/tag-des-offenen-denkmals-2026/', 'https://www.karlsdorf-neuthard.de/', 'Kultur,Essen,Neuthard', NULL, NULL, '2026-05-03 10:53:21', '2026-05-03 10:53:21');
INSERT INTO curated_events (id, title, normalized_title, date_start, date_end, time_raw, location, organizer, description, event_url, sources, tags, recurring_group_id, dedup_round, created_at, updated_at) VALUES (207161, 'Eltern-Baby-Café', NULL, '2026-09-14', '2026-09-14', '10:00', 'Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297', 'Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.', 'Mütter/Väter treffen sich zusammen mit Ihren Babys zum Erfahrungsaustausch.
Die Eltern profitieren vom Kontakt zu Gleichgesinnten, von den Anregungen für das Kind und von einem Kreis, in dem sie über Kindererziehung sprechen können.
Die Babys haben Spaß miteinander beim Singen, Spielen und Basteln.
Eltern-Baby-Cafe im MGH Flyer
KostenDie Teilnahme ist kostenfrei.
Die Veranstaltung findet nicht in den Ferien statt.
AnsprechpartnerinBarbara Hofheinz – Zertifizierte MütterpflegerinTelefon: 0176 49873115
