INSERT INTO curated_events (id, title, normalized_title, date_start, date_end, time_raw, location, organizer, description, event_url, sources, tags, recurring_group_id, dedup_round, created_at, updated_at) VALUES (207807, 'Weihnachtsfeier 2026', NULL, '2026-12-11', '2026-12-11', '19:00 - 22:00', 'Zehntscheuer 1737, Kronenstraße 1, Karlsdorf-Neuthard', 'Bürgerstiftung Karlsdorf-Neuthard', 'Der besinnlich-gesellige Jahresausklang unseres Vereins – exklusiv für alle Vereinsmitglieder der Bürgerstiftung Karlsdorf-Neuthard und die, die es noch werden wollen! Wir werden uns auch dieses Jahr etwas Besonderes für den gemeinsamen, stimmungsvollen, geselligen Abend überlegen. Was das Essen und das geplante Programm angeht, werden wir noch rechtzeitig informieren. Was wir schon mit Sicherheit wissen, ist, dass die Veranstaltung an unsere Vereinsmitglieder gerichtet ist und eine Anmeldung erforderlich sein wird. Noch kein Mitglied? Dann wird’s Zeit! Wer noch kein Mitglied ist, aber sich eh mit dem Gedanken trägt, der kann natürlich noch rechtzeitig beitreten und dann an der diesjährigen Weihnachtsfeier schon teilnehmen. Die Mitgliedserklärung zum Herunterladen gibt es auf der Startseite unserer Homepage ganz unten. Wir freuen uns auf dich und auf einen weiteren stimmungsvollen Abend in der Zehntscheuer!', 'https://buergerstiftung-kn.de/event/weihnachtsfeier-2026/', 'https://www.karlsdorf-neuthard.de/', 'Musik,Essen,Neuthard', NULL, NULL, '2026-05-03 10:53:21', '2026-05-03 10:53:21');
