INSERT INTO curated_events (id, title, normalized_title, date_start, date_end, time_raw, location, organizer, description, event_url, sources, tags, recurring_group_id, dedup_round, created_at, updated_at) VALUES (209269, 'Krabbelgruppe im ev. Gemeindehaus Staffort', NULL, '2028-01-26', '2028-01-26', '09:30', 'Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297', 'Kirchengemeinde Staffort-Büchenau', 'Bist du im Alter von 0 bis 3 Jahren?
Dann komm doch zum…

… Spielen
