INSERT INTO curated_events (id, title, normalized_title, date_start, date_end, time_raw, location, organizer, description, event_url, sources, tags, recurring_group_id, dedup_round, created_at, updated_at) VALUES (209306, 'Kinder- und Jugendtraining – Wilde 13', NULL, '2028-02-07', '2028-02-07', '18:00', 'Boulodrome der Wilden 13, Am Vogelpark 1A, Stutensee-Blankenloch, 76297', 'BSG Wilde 13 Stutensee e.V.', 'Das regelmäßige Kinder- und Jugendtraining der „Wilden 13“ bietet jungen Spielerinnen und Spielern die Möglichkeit, spielerisch in die Welt des Boule einzusteigen und ihre Technik zu verbessern.
Das Training findet wöchentlich im Boulodrome am Vogelpark statt und richtet sich an alle Kinder und Jugendlichen, die Spaß an Bewegung und Präzisionssport haben.
Kontakt bei Fragen: boehm.uwe@outlook.com
', 'https://stutenseekinderkalender.de/event/kinder-und-jugendtraining-wilde-13/2028-02-07/', 'https://stutenseekinderkalender.de', 'Sport,Kinder,Blankenloch', 206062, NULL, '2026-05-03 10:53:21', '2026-05-03 10:53:21');
INSERT INTO curated_events (id, title, normalized_title, date_start, date_end, time_raw, location, organizer, description, event_url, sources, tags, recurring_group_id, dedup_round, created_at, updated_at) VALUES (209307, 'Kükenstube – Betreuung für Kleinkinder bis 3 Jahre im ev. Gemeindehaus Friedrichstal', NULL, '2028-02-07', '2028-02-07', '09:00', 'Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297', 'Ev. Kirchengemeinde Friedrichstal', '
In der Kükenstube erleben Kinder bis 3 Jahre ein buntes Programm aus Spielen, Singen, Geschichten und kleinen Ausflügen. Unter liebevoller Betreuung lernen sie, sich in der Gruppe wohlzufühlen und erste Freundschaften zu schließen.
Montags ab 9.00 Uhr und donnerstags ab 8.30 Uhr jeweils bis 12.00 Uhr ist die Kükenstube im evangelischen Gemeindehaus in der Hirschstr. 22 geöffnet.

Weitere Informationen, wie Betreuungszeiten, Anmeldung, zusätzliche Hinweise und aktuelle Änderungen findet ihr auf der Webseite des Veranstalters.
Ansprechpartnerin:
Sabrina Strohal, Tel. 387483 oder 0160 98567729
Flyer Kükenstube 2025', 'https://stutenseekinderkalender.de/event/kuekenstube-betreuung-fuer-kleinkinder-bis-3-jahre-im-ev-gemeindehaus-friedrichstal/2028-02-07/', 'https://stutenseekinderkalender.de', 'Musik,Kirche,Friedrichstal', NULL, NULL, '2026-05-03 10:53:21', '2026-05-03 10:53:21');
INSERT INTO curated_events (id, title, normalized_title, date_start, date_end, time_raw, location, organizer, description, event_url, sources, tags, recurring_group_id, dedup_round, created_at, updated_at) VALUES (209308, 'Spiele-Treff vom Teenie bis zum Oldie', NULL, '2028-02-07', '2028-02-07', '16:00', 'Mehrgenerationenhaus Stutensee-Blankenloch, Seegrabenweg 5, Stutensee, 76297', 'Mehrgenerationenhaus Bürgerwerkstatt Stutensee e.V.', 'Neue und alte Brett-, Karten-, Knobel-, Strategie- und Ratespiele. Gerne könnt ihr zum Zocken eure Lieblingsspiele mitbringen.
