INSERT INTO curated_events (id, title, normalized_title, date_start, date_end, time_raw, location, organizer, description, event_url, sources, tags, recurring_group_id, dedup_round, created_at, updated_at) VALUES (209323, 'Tee- und Spielstube', NULL, '2028-02-10', '2028-02-10', '16:00', 'Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298', 'Flüchtlingshilfe Stutensee e.V.', 'Die Tee- und Spielstube lädt zu gemütlichen Nachmittagen ein, an denen sich Menschen aus verschiedenen Kulturen begegnen, austauschen und miteinander Zeit verbringen können. Bei Tee, Kaffee und Gebäck entstehen Gespräche, Freundschaften und schöne Momente. Auch Kinder können spielen, basteln oder einfach Spaß haben, während die Erwachsenen ins Gespräch kommen.

Für Geflüchtete, Migrantinnen, Ehrenamtliche und alle interessierten Bürgerinnen
Jeden Donnerstag von 16:00 bis 18:00 Uhr (nicht in den Schulferien und an Feiertagen)

Anmeldung: Doris Maier, teststube-bl@fluechtlingshilfe-stutensee.de ', 'https://stutenseekinderkalender.de/event/tee-und-spielstube/2028-02-10/', 'https://stutenseekinderkalender.de', 'Kultur,Kinder,Blankenloch', 206121, NULL, '2026-05-03 10:53:21', '2026-05-03 10:53:21');
INSERT INTO curated_events (id, title, normalized_title, date_start, date_end, time_raw, location, organizer, description, event_url, sources, tags, recurring_group_id, dedup_round, created_at, updated_at) VALUES (209324, 'Teen Girls im GrauBau', NULL, '2028-02-10', '2028-02-10', '18:00', 'GrauBau Jugendzentrum Stutensee, Seegrabenweg 7, Stutensee, 76297', 'GrauBau Jugendzentrum Stutensee', 'Im Teen Girls Club treffen sich Mädchen ab 13 Jahren, um gemeinsam zu reden, kreativ zu sein und Spaß zu haben. Ob DIY-Projekte, Musik, Kochen oder einfach nur Zeit miteinander verbringen – hier kannst du dich ausprobieren, austauschen und neue Freundschaften knüpfen. Jeden Donnerstag, 18:00 – 20:00 Uhr
