INSERT INTO curated_events (id, title, normalized_title, date_start, date_end, time_raw, location, organizer, description, event_url, sources, tags, recurring_group_id, dedup_round, created_at, updated_at) VALUES (210247, 'Pfadfinder*innengruppe (11–15 Jahre)', NULL, '2028-11-07', '2028-11-07', '17:30', 'Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297', 'Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler', 'Pfadfinderinnen und Pfadfinder sind Mädchen und Jungen im Alter von 11 bis 15 Jahren.
Geländespiele, Pfadfindertechniken, Naturkunde und vor allem gemeinsame Fahrten – einfach mit Rucksack für ein Wochenende fortzufahren – sind pfadfinderische Erlebnisse, von denen man noch lange am Lagerfeuer erzählen kann. Dabei lernen Pfadfinderinnen und Pfadfinder in ihren Sippen schon früh, wie es ist, für sich und für andere Verantwortung zu übernehmen.
Höhepunkte in einem Pfadfinderleben sind natürlich das alle vier Jahre stattfindende Bundeslager und das World Scout Jamboree (Weltpfadfindertreffen).


Der Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!
Unsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.




', 'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-11-15-jahre/2028-11-07/', 'https://stutenseekinderkalender.de', 'Kinder,Workshop,Friedrichstal,Spöck', 206081, NULL, '2026-05-03 10:53:21', '2026-05-03 10:53:21');
INSERT INTO curated_events (id, title, normalized_title, date_start, date_end, time_raw, location, organizer, description, event_url, sources, tags, recurring_group_id, dedup_round, created_at, updated_at) VALUES (210248, 'Pfadfinder*innengruppe Wölflinge', NULL, '2028-11-07', '2028-11-07', '17:30', 'Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler, Spöcker Weg 2, Stutensee-Friedrichstal, 76297', 'Bund der Pfadfinder*innen &#8211; Pfadfinderstamm Adler', 'Wölflinge heißen die 7 bis 11-jährigen Jungen und Mädchen. Die Wölflingsgruppe trifft sich regelmäßig zur gemeinsamen Gruppenstunde. Im Mittelpunkt stehen Spiel, Gemeinschaft, Naturerlebnisse und altersgerechte Pfadfinderaktivitäten.
Der Bund der Pfadfinder*innen e.V. (BdP) ist politisch unabhängig und interkonfessionell. Alle Kinder und Jugendlichen sind herzlich willkommen. Wenn du Interesse hast, komm doch einfach mal vorbei!
Unsere Gruppenstunden sind jeden Dienstag (außer in den Schulferien) am Pfadfinderheim in Friedrichstal.', 'https://stutenseekinderkalender.de/event/pfadfinderinnengruppe-woelflinge/2028-11-07/', 'https://stutenseekinderkalender.de', 'Kinder,Workshop,Friedrichstal,Spöck', 206082, NULL, '2026-05-03 10:53:21', '2026-05-03 10:53:21');
INSERT INTO curated_events (id, title, normalized_title, date_start, date_end, time_raw, location, organizer, description, event_url, sources, tags, recurring_group_id, dedup_round, created_at, updated_at) VALUES (210249, 'Schach für Schüler, Jugendliche & Anfänger', NULL, '2028-11-07', '2028-11-07', '16:30', 'Altes Rathaus Blankenloch, Hauptstraße 80, Stutensee-Blankenloch, 76298', 'Schachclub Blankenloch 1947 e.V.', 'Im Schachclub Blankenloch treffen sich junge Tüftler und neugierige Köpfe, um gemeinsam die Welt der Schachfiguren zu entdecken.Hier lernen Anfänger spielerisch die Grundlagen des Schachspiels, während Fortgeschrittene ihre Strategien verbessern und sich in spannenden Partien messen können.
Ein Ort, an dem Konzentration, Logik und Gemeinschaft gefördert werden – perfekt für Kinder, die Freude am Denken und Knobeln haben.
Anmeldung: Gerhard Crocoll, 015233943935', 'https://stutenseekinderkalender.de/event/schach-fuer-schueler-jugendliche-anfaenger/2028-11-07/', 'https://stutenseekinderkalender.de', 'Kirche,Kinder,Blankenloch', 206083, NULL, '2026-05-03 10:53:21', '2026-05-03 10:53:21');
INSERT INTO curated_events (id, title, normalized_title, date_start, date_end, time_raw, location, organizer, description, event_url, sources, tags, recurring_group_id, dedup_round, created_at, updated_at) VALUES (210250, 'Seepferdchengarde (6–10 Jahre)', NULL, '2028-11-07', '2028-11-07', '16:00', 'Vereinsheim des Karnevalsclubs Die Piraten, Seegrabenweg 9, Stutensee-Blankenloch, 76297', 'Karnevalsclub &#8222;Die Piraten&#8220; Stutensee e.V.', 'Die Seepferdchengarde begeistert mit Kreativität, Rhythmus und Spaß am Tanzen!Kinder im Grundschulalter trainieren hier Tanztechnik, Ausdruck und Koordination – ideal für kleine Tänzer:innen mit großen Träumen.

Dienstags, 16:00–18:00 Uhr & Freitags, 15:00–17:00 Uhr
Veranstalter: Karnevalsclub Die Piraten Blankenloch e. V.
', 'https://stutenseekinderkalender.de/event/seepferdchengarde-6-10-jahre-2/2028-11-07/', 'https://stutenseekinderkalender.de', 'Sport,Kinder,Blankenloch', NULL, NULL, '2026-05-03 10:53:21', '2026-05-03 10:53:21');
INSERT INTO curated_events (id, title, normalized_title, date_start, date_end, time_raw, location, organizer, description, event_url, sources, tags, recurring_group_id, dedup_round, created_at, updated_at) VALUES (210251, 'Selbsthilfegruppe für Angehörige von AD(H)S-Kindern', NULL, '2028-11-07', '2028-11-07', '19:00', 'Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus, Rheinstraße Ost 14, Stutensee-Friedrichstal, 76297', 'Familienzentrum Friedrichstal &#8211; Kult Café im Alten Rathaus', 'Habt ihr ein sehr verträumtes oder lebhaftes, aber zugleich kreatives Kind? Euer Sohn oder eure Tochter bringt euch mit lustigen, aber manchmal haarsträubenden Ideen an die Grenzen? Dann seid ihr bei dieser offenen Elternrunde genau richtig.
Die Selbsthilfegruppe richtet sich an Eltern und Angehörige von Kindern mit AD(H)S oder dem Verdacht darauf. Hier könnt ihr euch in einer vertraulichen und unterstützenden Atmosphäre austauschen, Erfahrungen teilen und gegenseitig stärken.
Hinweis:Zu Beginn des ersten Treffens wird eine kurze Datenschutz-/Verschwiegenheitserklärung unterzeichnet, um einen geschützten Raum für alle zu gewährleisten.

Jeden 1. Dienstag im Monat, 19:00 – 20:30 Uhr (nicht in den Schulferien)
Kostenfrei

Anmeldung: hauserbeate@web.de oder 072494534 (Mo–Fr ab 10 Uhr)', 'https://stutenseekinderkalender.de/event/selbsthilfegruppe-fuer-angehoerige-von-adhs-kindern/2028-11-07/', 'https://stutenseekinderkalender.de', 'Kinder,Handwerk,Friedrichstal', 206085, NULL, '2026-05-03 10:53:21', '2026-05-03 10:53:21');
INSERT INTO curated_events (id, title, normalized_title, date_start, date_end, time_raw, location, organizer, description, event_url, sources, tags, recurring_group_id, dedup_round, created_at, updated_at) VALUES (210252, 'Eltern-Kind-Kreis in Friedrichstal', NULL, '2028-11-08', '2028-11-08', '10:00', 'Ev. Gemeindehaus Friedrichstal, Hirschstraße 22, Stutensee, 76297', 'Ev. Kirchengemeinde Friedrichstal', 'Ein Treffpunkt für Mütter und Väter mit Kindern von 0–3 Jahren. Jeden Mittwoch, 10:00 – 11:30 Uhr. Gemeinsam wird gesungen, gespielt, gebastelt und gelacht. Die Kinder entdecken die Welt, während die Eltern sich austauschen und neue Kontakte knüpfen können. Hin und wieder steht auch ein gemeinsames Frühstück oder Bastelangebot auf dem Programm.
Ansprechpartnerin: Corinna Konrad, 01725618123', 'https://stutenseekinderkalender.de/event/eltern-kind-kreis-in-friedrichstal/2028-11-08/', 'https://stutenseekinderkalender.de', 'Sport,Kinder,Friedrichstal', 206090, NULL, '2026-05-03 10:53:21', '2026-05-03 10:53:21');
INSERT INTO curated_events (id, title, normalized_title, date_start, date_end, time_raw, location, organizer, description, event_url, sources, tags, recurring_group_id, dedup_round, created_at, updated_at) VALUES (210253, 'Krabbelgruppe im ev. Gemeindehaus Staffort', NULL, '2028-11-08', '2028-11-08', '09:30', 'Ev. Gemeindehaus Staffort, Gartenstraße 31, Stutensee-Staffort, 76297', 'Kirchengemeinde Staffort-Büchenau', 'Bist du im Alter von 0 bis 3 Jahren?
Dann komm doch zum…

… Spielen
… Singen
… Freunde finden
… Basteln und Malen
… Feste feiern
und weitere Aktionen in die Krabbelgruppe.

Wir freuen uns auf dich!

Ansprechpartner: Janine Kirchner', 'https://stutenseekinderkalender.de/event/krabbelgruppe-im-ev-gemeindehaus-staffort/2028-11-08/', 'https://stutenseekinderkalender.de', 'Musik,Kultur,Staffort,Büchenau', 206097, NULL, '2026-05-03 10:53:21', '2026-05-03 10:53:21');
